export const topics = [
  // ==================== DATA STRUCTURES (25) ====================
  ["Software Engineering", "What is an array and what are its time complexities?", "array-complexities", "Explain arrays and their complexity.", "**Direct answer :**\nAn array stores elements in an indexed sequence, typically in contiguous memory for a conventional array. Because an index can be translated directly into an element location, random access is O(1). Inserting or deleting in the middle is normally O(n) because elements may need to be shifted. A dynamic array can append in O(1) amortized time, although an individual resize can cost O(n).\n\nKey points to remember:\n- Arrays are fixed-size in many languages (static) or dynamic (like ArrayList).\n- Access by index is constant time because of direct memory addressing.\n- Insertion at the end is O(1) if space available, else O(n) for resizing.\n- Insertion/deletion at arbitrary position requires shifting elements, O(n).\n- Searching unsorted array is O(n); sorted array can be O(log n) with binary search.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your fundamental knowledge of data structures and their performance trade-offs, which is crucial for algorithm design and optimization.\n\n**Breaking it down :**\n- Arrays are fixed-size in many languages (static) or dynamic (like ArrayList).\n- Access by index is constant time because of direct memory addressing.\n- Insertion at the end is O(1) if space available, else O(n) for resizing.\n- Insertion/deletion at arbitrary position requires shifting elements, O(n).\n- Searching unsorted array is O(n); sorted array can be O(log n) with binary search.\n\n**How to structure your spoken answer :**\nStart with a definition. Then list complexities for access, search, insertion, and deletion. Mention the difference between static and dynamic arrays. Give examples of when to use arrays vs linked lists.\n\n**Follow-up angle to anticipate :**\nBe ready to compare arrays with linked lists, and discuss dynamic resizing strategies (like doubling)."],
  ["Software Engineering", "What is a linked list and what are its types?", "linked-list-types", "Explain linked lists.", "**Direct answer :**\nA linked list is a linear data structure made of nodes, where each node stores data and one or more links to other nodes. A singly linked list points to the next node, a doubly linked list has both next and previous links, and a circular list connects the final node back to the first. Linked lists provide O(1) insertion or deletion at a known position when the required node/link is already available, but finding that position is usually O(n).\n\nKey points to remember:\n- Singly: each node points to next; traversable only forward.\n- Doubly: each node points to next and prev; allows bidirectional traversal.\n- Circular: last node points to head (or first).\n- Advantages: dynamic size, easy insertions/deletions (O(1) if you have the node). Disadvantages: no random access, extra memory for pointers.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of pointer-based structures and their use cases.\n\n**Breaking it down :**\n- Singly: each node points to next; traversable only forward.\n- Doubly: each node points to next and prev; allows bidirectional traversal.\n- Circular: last node points to head (or first).\n- Advantages: dynamic size, easy insertions/deletions (O(1) if you have the node). Disadvantages: no random access, extra memory for pointers.\n\n**How to structure your spoken answer :**\nDefine linked list. List types with brief descriptions. Mention time complexities: insertion/deletion O(1) at head, O(n) for search. Compare with arrays.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a linked list reversal or detect cycles."],
  ["Software Engineering", "What is a stack and what are its operations?", "stack-operations", "Explain stack.", "**Direct answer :**\nA stack is a LIFO (Last In, First Out) data structure. Operations: push (add), pop (remove), peek (top), isEmpty. Implemented using arrays or linked lists.\n\nKey points to remember:\n- Push: O(1) if array has space or linked list.\n- Pop: O(1).\n- Peek: O(1).\n- Used in function call stack, undo/redo, backtracking.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of basic data structures used in many algorithms (e.g., recursion, expression evaluation).\n\n**Breaking it down :**\n- Push: O(1) if array has space or linked list.\n- Pop: O(1).\n- Peek: O(1).\n- Used in function call stack, undo/redo, backtracking.\n\n**How to structure your spoken answer :**\nDefine stack. List operations and complexities. Give examples of use cases. Mention implementations.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a stack using an array vs linked list, and discuss overflow/underflow."],
  ["Software Engineering", "What is a queue and what are its operations?", "queue-operations", "Explain queue.", "**Direct answer :**\nA queue is a FIFO (First In, First Out) data structure. Operations: enqueue (add), dequeue (remove), front, isEmpty. Implemented using arrays (circular) or linked lists.\n\nKey points to remember:\n- Enqueue: O(1) (if using linked list or circular array with tail pointer).\n- Dequeue: O(1).\n- Used in BFS, task scheduling, buffering.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of sequential processing and scheduling.\n\n**Breaking it down :**\n- Enqueue: O(1) (if using linked list or circular array with tail pointer).\n- Dequeue: O(1).\n- Used in BFS, task scheduling, buffering.\n\n**How to structure your spoken answer :**\nDefine queue. List operations. Mention circular arrays to avoid shifting. Give use cases.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a queue with arrays and discuss the circular buffer concept."],
  ["Software Engineering", "What is a hash table and how does it handle collisions?", "hash-table-collisions", "Explain hash table.", "**Direct answer :**\nA hash table is a data structure that maps keys to values using a hash function. Collisions occur when two keys hash to the same index. Common collision resolution: chaining (linked list) and open addressing (probing).\n\nKey points to remember:\n- Hash function computes index from key.\n- Collisions: handle via separate chaining (each bucket holds a list) or open addressing (find next available slot, e.g., linear probing, quadratic probing).\n- Average-case O(1) for get/put, worst-case O(n) if many collisions.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of efficient key-value storage and resolving conflicts.\n\n**Breaking it down :**\n- Hash function computes index from key.\n- Collisions: handle via separate chaining (each bucket holds a list) or open addressing (find next available slot, e.g., linear probing, quadratic probing).\n- Average-case O(1) for get/put, worst-case O(n) if many collisions.\n\n**How to structure your spoken answer :**\nDefine hash table. Explain hash function. Describe collision handling with examples. Mention load factor and resizing.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the trade-offs between chaining and open addressing, and how to choose a good hash function."],
  ["Software Engineering", "What is a binary tree and its traversal methods?", "binary-tree-traversal", "Explain binary tree.", "**Direct answer :**\nA binary tree is a tree where each node has at most two children. Traversals: inorder (left-root-right), preorder (root-left-right), postorder (left-right-root), and level order (breadth-first).\n\nKey points to remember:\n- Inorder: used to get sorted order in BST.\n- Preorder: used to copy the tree.\n- Postorder: used to delete the tree.\n- Level order: BFS using queue.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of hierarchical data and tree traversal algorithms.\n\n**Breaking it down :**\n- Inorder: used to get sorted order in BST.\n- Preorder: used to copy the tree.\n- Postorder: used to delete the tree.\n- Level order: BFS using queue.\n\n**How to structure your spoken answer :**\nDefine binary tree. List traversals with order. Explain each with a small example. Mention that recursion is common but iterative is also possible.\n\n**Follow-up angle to anticipate :**\nBe ready to implement traversals iteratively and discuss time/space complexity."],
  ["Software Engineering", "What is a Binary Search Tree (BST) and its properties?", "bst-properties", "Explain BST.", "**Direct answer :**\nA BST is a binary tree where for each node, all left descendants have keys less than the node, and all right descendants have keys greater. This enables O(log n) search, insert, delete on average.\n\nKey points to remember:\n- Search: compare key, go left or right.\n- Insert: like search, then attach as leaf.\n- Delete: three cases (leaf, one child, two children with successor).\n- Worst-case O(n) if unbalanced; balanced trees (AVL, Red-Black) guarantee O(log n).\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of sorted data structures and their operations.\n\n**Breaking it down :**\n- Search: compare key, go left or right.\n- Insert: like search, then attach as leaf.\n- Delete: three cases (leaf, one child, two children with successor).\n- Worst-case O(n) if unbalanced; balanced trees (AVL, Red-Black) guarantee O(log n).\n\n**How to structure your spoken answer :**\nDefine BST. Explain the ordering property. Describe operations with time complexities. Mention balancing.\n\n**Follow-up angle to anticipate :**\nBe ready to explain how to delete a node with two children, and discuss self-balancing trees."],
  ["Software Engineering", "What is an AVL tree?", "avl-tree", "Explain AVL tree.", "**Direct answer :**\nAn AVL tree is a self-balancing BST where the height difference between left and right subtrees (balance factor) is at most 1 for every node. Rotations (LL, RR, LR, RL) are used to restore balance.\n\nKey points to remember:\n- Balance factor = height(left) - height(right).\n- If factor becomes -2 or 2, rotations are performed.\n- Insert/delete O(log n) guaranteed.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of balancing mechanisms and their implementations.\n\n**Breaking it down :**\n- Balance factor = height(left) - height(right).\n- If factor becomes -2 or 2, rotations are performed.\n- Insert/delete O(log n) guaranteed.\n\n**How to structure your spoken answer :**\nDefine AVL tree. Explain balance factor and rotations. Mention that it's more rigid than Red-Black but provides faster lookups.\n\n**Follow-up angle to anticipate :**\nBe ready to describe the rotation types and when each is applied."],
  ["Software Engineering", "What is a heap and what are its types?", "heap-types", "Explain heap.", "**Direct answer :**\nA heap is a tree-based data structure that satisfies the heap property: in a max-heap, parent is >= children; in a min-heap, parent <= children. It is typically implemented as an array (complete binary tree).\n\nKey points to remember:\n- Insert: O(log n) (bubble up).\n- Extract max/min: O(log n) (bubble down after removing root).\n- Build heap: O(n) using heapify.\n- Used in priority queues, heapsort, Dijkstra.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of priority queues and heapsort.\n\n**Breaking it down :**\n- Insert: O(log n) (bubble up).\n- Extract max/min: O(log n) (bubble down after removing root).\n- Build heap: O(n) using heapify.\n- Used in priority queues, heapsort, Dijkstra.\n\n**How to structure your spoken answer :**\nDefine heap. Explain the heap property. Mention array representation. Give operations and complexities.\n\n**Follow-up angle to anticipate :**\nBe ready to implement heapify and discuss heapsort."],
  ["Software Engineering", "What is a graph and its representations?", "graph-representations", "Explain graph.", "**Direct answer :**\nA graph is a collection of nodes (vertices) and edges connecting them. Representations: adjacency matrix (2D array) and adjacency list (array of lists).\n\nKey points to remember:\n- Adjacency matrix: O(V^2) space, O(1) edge check, good for dense graphs.\n- Adjacency list: O(V+E) space, O(degree) edge check, good for sparse graphs.\n- Other: edge list.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of graph structures used in many algorithms (e.g., traversal, shortest path).\n\n**Breaking it down :**\n- Adjacency matrix: O(V^2) space, O(1) edge check, good for dense graphs.\n- Adjacency list: O(V+E) space, O(degree) edge check, good for sparse graphs.\n- Other: edge list.\n\n**How to structure your spoken answer :**\nDefine graph. Explain representations with pros/cons. Mention directed vs undirected, weighted vs unweighted.\n\n**Follow-up angle to anticipate :**\nBe ready to implement BFS/DFS using these representations."],
  ["Software Engineering", "What is the difference between a tree and a graph?", "tree-vs-graph", "Compare tree and graph.", "**Direct answer :**\nA tree is a connected, acyclic graph with N nodes and N-1 edges. A graph can have cycles and may be disconnected. Trees have a hierarchical structure, graphs can have arbitrary connections.\n\nKey points to remember:\n- Tree: exactly one path between any two nodes, no cycles.\n- Graph: may have multiple paths, cycles, can be disconnected.\n- Trees are special cases of graphs.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to check if you understand the fundamental distinction and when to use each.\n\n**Breaking it down :**\n- Tree: exactly one path between any two nodes, no cycles.\n- Graph: may have multiple paths, cycles, can be disconnected.\n- Trees are special cases of graphs.\n\n**How to structure your spoken answer :**\nDefine both. Highlight differences in edges, connectivity, and cycles. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss tree traversal vs graph traversal."],
  ["Software Engineering", "What is a trie (prefix tree)?", "trie", "Explain trie.", "**Direct answer :**\nA trie is a tree-like data structure used for efficient retrieval of strings. Each node represents a character, and paths from root to leaf form strings. It supports O(L) insert, search, and prefix lookup, where L is length of the string.\n\nKey points to remember:\n- Each node has children for characters.\n- Insert: traverse/create nodes.\n- Search: traverse; if path exists and end marker, found.\n- Prefix: traverse; if path exists, all descendants are valid.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of string processing and autocomplete systems.\n\n**Breaking it down :**\n- Each node has children for characters.\n- Insert: traverse/create nodes.\n- Search: traverse; if path exists and end marker, found.\n- Prefix: traverse; if path exists, all descendants are valid.\n\n**How to structure your spoken answer :**\nDefine trie. Explain its structure and operations. Mention use cases: autocomplete, spell checker. Compare with hash table.\n\n**Follow-up angle to anticipate :**\nBe ready to implement insert and search, and discuss memory usage."],
  ["Software Engineering", "What is a segment tree and its use cases?", "segment-tree", "Explain segment tree.", "**Direct answer :**\nA segment tree is a binary tree used for range queries and updates on an array. It stores aggregate information (e.g., sum, min, max) for segments. Operations: range query and point/range update in O(log n).\n\nKey points to remember:\n- Build: O(n).\n- Query: O(log n) by combining children.\n- Update: O(log n).\n- Lazy propagation for range updates.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of advanced data structures for competitive programming.\n\n**Breaking it down :**\n- Build: O(n).\n- Query: O(log n) by combining children.\n- Update: O(log n).\n- Lazy propagation for range updates.\n\n**How to structure your spoken answer :**\nDefine segment tree. Explain its purpose: efficient range queries. Give example: sum of range. Mention lazy propagation for range updates.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to implement range sum queries and updates."],
  ["Software Engineering", "What is the difference between a stack and a queue?", "stack-vs-queue", "Compare stack and queue.", "**Direct answer :**\nStack is LIFO, queue is FIFO. Stack uses push/pop; queue uses enqueue/dequeue. Stacks are used for recursion, queues for BFS.\n\nKey points to remember:\n- Stack: add/remove from same end (top).\n- Queue: add at one end (rear), remove from other (front).\n- Both can be implemented with arrays or linked lists.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to check your understanding of basic ADTs.\n\n**Breaking it down :**\n- Stack: add/remove from same end (top).\n- Queue: add at one end (rear), remove from other (front).\n- Both can be implemented with arrays or linked lists.\n\n**How to structure your spoken answer :**\nDefine both. Contrast order of operations. Give examples of each.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a queue using two stacks."],
  ["Software Engineering", "What is the difference between a linked list and an array?", "linkedlist-vs-array", "Compare linked list and array.", "**Direct answer :**\nArrays have contiguous memory, O(1) access, but fixed size (or amortized) and O(n) insert/delete in middle. Linked lists use dynamic memory, O(1) insertion/deletion at head, but O(n) access.\n\nKey points to remember:\n- Array: random access, cache-friendly, but resizing cost.\n- Linked list: no random access, extra pointer memory, but dynamic size and easy insertion/deletion.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to choose the right structure based on operations.\n\n**Breaking it down :**\n- Array: random access, cache-friendly, but resizing cost.\n- Linked list: no random access, extra pointer memory, but dynamic size and easy insertion/deletion.\n\n**How to structure your spoken answer :**\nCompare by memory, access, insertion/deletion, and use cases. Give examples: array for frequent access, linked list for frequent insert/delete.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss singly vs doubly linked lists and their overhead."],
  ["Software Engineering", "What is a circular queue and why is it used?", "circular-queue", "Explain circular queue.", "**Direct answer :**\nA circular queue connects the last position back to the first, allowing reuse of empty slots. It solves the problem of wasted space in a linear queue after dequeue operations. It uses head and tail pointers and modulo arithmetic.\n\nKey points to remember:\n- Enqueue: increment tail modulo size.\n- Dequeue: increment head modulo size.\n- Full condition: (tail+1)%size == head (if reserving one slot).\n- Used in buffering (e.g., circular buffers).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of efficient queue implementations.\n\n**Breaking it down :**\n- Enqueue: increment tail modulo size.\n- Dequeue: increment head modulo size.\n- Full condition: (tail+1)%size == head (if reserving one slot).\n- Used in buffering (e.g., circular buffers).\n\n**How to structure your spoken answer :**\nDefine circular queue. Explain the problem it solves. Describe the pointer management. Give use cases.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a circular queue and discuss edge conditions."],
  ["Software Engineering", "What is a priority queue?", "priority-queue", "Explain priority queue.", "**Direct answer :**\nA priority queue is an abstract data type in which removal returns an element according to priority rather than simply by insertion time. A min-priority queue returns the smallest priority value first, while a max-priority queue returns the largest. A binary heap is a common implementation, giving O(log n) insertion and removal of the highest-priority element and O(1) access to that element.\n\nKey points to remember:\n- Insert: O(log n) with heap.\n- Extract max/min: O(log n).\n- Applications: Dijkstra, Huffman coding, CPU scheduling.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of scheduling and ordering algorithms.\n\n**Breaking it down :**\n- Insert: O(log n) with heap.\n- Extract max/min: O(log n).\n- Applications: Dijkstra, Huffman coding, CPU scheduling.\n\n**How to structure your spoken answer :**\nDefine priority queue. Explain the heap implementation. Mention other implementations (binary heap, binomial heap).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to implement a priority queue with a heap."],
  ["Software Engineering", "What is a map/dictionary and what are its implementations?", "map-implementations", "Explain map.", "**Direct answer :**\nA map (or dictionary) is a collection of key-value pairs. Common implementations: hash table (HashMap), tree-based (TreeMap), and linked hash map. Each has different performance and ordering guarantees.\n\nKey points to remember:\n- HashMap: O(1) average, unordered.\n- TreeMap: O(log n) sorted order.\n- LinkedHashMap: O(1) with insertion order.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of associative arrays and their trade-offs.\n\n**Breaking it down :**\n- HashMap: O(1) average, unordered.\n- TreeMap: O(log n) sorted order.\n- LinkedHashMap: O(1) with insertion order.\n\n**How to structure your spoken answer :**\nDefine map. List implementations with characteristics. Mention when to choose each.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss hash collisions and Java's ConcurrentHashMap."],
  ["Software Engineering", "What is a set and its implementations?", "set-implementations", "Explain set.", "**Direct answer :**\nA set is a collection of unique elements. Implementations: HashSet (hash table), TreeSet (tree), LinkedHashSet (insertion order).\n\nKey points to remember:\n- HashSet: O(1) average, no order.\n- TreeSet: O(log n), sorted.\n- LinkedHashSet: O(1), insertion order.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of collections and their properties.\n\n**Breaking it down :**\n- HashSet: O(1) average, no order.\n- TreeSet: O(log n), sorted.\n- LinkedHashSet: O(1), insertion order.\n\n**How to structure your spoken answer :**\nDefine set. Explain the implementations and their trade-offs. Mention use cases: deduplication, membership testing.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between set and list."],
  ["Software Engineering", "What is a disjoint-set (union-find)?", "union-find", "Explain union-find.", "**Direct answer :**\nA disjoint-set data structure tracks partitions of a set into disjoint subsets. It supports two operations: find (determine which subset an element belongs to) and union (merge two subsets). Optimized with path compression and union by rank, achieving near-constant amortized time.\n\nKey points to remember:\n- Find: follows parent pointers to root; path compression flattens.\n- Union: attaches smaller tree under larger (rank).\n- Used in Kruskal's MST, dynamic connectivity.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of graph connectivity and cycle detection.\n\n**Breaking it down :**\n- Find: follows parent pointers to root; path compression flattens.\n- Union: attaches smaller tree under larger (rank).\n- Used in Kruskal's MST, dynamic connectivity.\n\n**How to structure your spoken answer :**\nDefine union-find. Explain operations and optimizations. Give applications.\n\n**Follow-up angle to anticipate :**\nBe ready to implement find and union with path compression."],
  ["Software Engineering", "What is a suffix tree?", "suffix-tree", "Explain suffix tree.", "**Direct answer :**\nA suffix tree is a compressed trie containing all suffixes of a string. It can support pattern matching and several substring queries in time proportional to the pattern length after the structure has been built, with linear-size construction possible using algorithms such as Ukkonen's algorithm under standard assumptions. Its main trade-off is implementation complexity and substantial memory usage compared with simpler structures such as suffix arrays.\n\nKey points to remember:\n- Contains all suffixes as paths.\n- Each edge labeled with substrings.\n- Useful for bioinformatics, text search.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of advanced string data structures.\n\n**Breaking it down :**\n- Contains all suffixes as paths.\n- Each edge labeled with substrings.\n- Useful for bioinformatics, text search.\n\n**How to structure your spoken answer :**\nDefine suffix tree. Explain its purpose and complexity. Mention applications.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss suffix array as an alternative."],
  ["Software Engineering", "What is a bloom filter?", "bloom-filter", "Explain bloom filter.", "**Direct answer :**\nA bloom filter is a probabilistic data structure for set membership. It allows false positives but no false negatives. It uses multiple hash functions and a bit array. Space efficient but probabilistic.\n\nKey points to remember:\n- Insert: set bits at hash positions.\n- Query: check all bits; if any 0, definitely absent; if all 1, probably present.\n- Used in databases, caching to avoid expensive lookups.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of space-efficient algorithms and probabilistic structures.\n\n**Breaking it down :**\n- Insert: set bits at hash positions.\n- Query: check all bits; if any 0, definitely absent; if all 1, probably present.\n- Used in databases, caching to avoid expensive lookups.\n\n**How to structure your spoken answer :**\nDefine bloom filter. Explain the principle. Discuss false positives and how to control them. Give use cases.\n\n**Follow-up angle to anticipate :**\nBe ready to explain how to choose hash functions and bit size."],
  ["Software Engineering", "What is the difference between a B-tree and a B+ tree?", "btree-vs-bplus", "Compare B-tree and B+ tree.", "**Direct answer :**\nB-tree and B+ tree are balanced tree structures for storage systems. B+ tree stores all keys in leaves linked sequentially, while B-tree stores keys in internal nodes too. B+ trees are better for range queries.\n\nKey points to remember:\n- B-tree: each node holds keys and data pointers; internal nodes also hold data.\n- B+ tree: internal nodes only hold keys for routing; all data is in leaves, which are linked for sequential access.\n- B+ tree: higher fanout, less height, efficient range scan.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of database indexing.\n\n**Breaking it down :**\n- B-tree: each node holds keys and data pointers; internal nodes also hold data.\n- B+ tree: internal nodes only hold keys for routing; all data is in leaves, which are linked for sequential access.\n- B+ tree: higher fanout, less height, efficient range scan.\n\n**How to structure your spoken answer :**\nDefine both. Contrast structure and usage. Explain why B+ trees are used in databases.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how they are used in indexing."],
  ["Software Engineering", "What is a skip list?", "skip-list", "Explain skip list.", "**Direct answer :**\nA skip list is a probabilistic data structure that allows O(log n) average search, insertion, and deletion. It consists of multiple levels of linked lists, with higher levels skipping nodes. Simpler to implement than balanced trees.\n\nKey points to remember:\n- Each node has forward pointers at different levels.\n- Search: start from highest level, move forward until exceed key, then descend.\n- Insert: randomly choose level.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of alternative to balanced trees.\n\n**Breaking it down :**\n- Each node has forward pointers at different levels.\n- Search: start from highest level, move forward until exceed key, then descend.\n- Insert: randomly choose level.\n\n**How to structure your spoken answer :**\nDefine skip list. Explain its structure and operations. Mention its probabilistic nature and use in concurrent systems.\n\n**Follow-up angle to anticipate :**\nBe ready to explain how random levels are generated."],
  ["Software Engineering", "What is a graph cycle and how to detect it?", "graph-cycle-detection", "Explain cycle detection.", "**Direct answer :**\nA cycle in a graph is a path where the start and end vertices are the same. In undirected graphs, DFS with parent detection; in directed graphs, DFS with recursion stack (back edges).\n\nKey points to remember:\n- Undirected: if during DFS we encounter a visited vertex that is not the parent, cycle.\n- Directed: maintain a recursion stack; if we see a vertex already in the stack, cycle.\n- Union-find can also detect cycles in undirected.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your graph algorithm skills.\n\n**Breaking it down :**\n- Undirected: if during DFS we encounter a visited vertex that is not the parent, cycle.\n- Directed: maintain a recursion stack; if we see a vertex already in the stack, cycle.\n- Union-find can also detect cycles in undirected.\n\n**How to structure your spoken answer :**\nDefine cycle. Explain detection methods for both directed and undirected. Give algorithm outline.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss topological sorting for DAGs."],

  // ==================== ALGORITHMS (25) ====================
  ["Software Engineering", "What is the time complexity of binary search?", "binary-search-complexity", "Explain binary search.", "**Direct answer :**\nBinary search has O(log n) time complexity. It works on sorted arrays by repeatedly dividing the search interval in half.\n\nKey points to remember:\n- Compare target with middle element.\n- If equal, found.\n- If target less, search left half; else right half.\n- Each step halves the array, hence log n.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of divide-and-conquer and logarithmic complexity.\n\n**Breaking it down :**\n- Compare target with middle element.\n- If equal, found.\n- If target less, search left half; else right half.\n- Each step halves the array, hence log n.\n\n**How to structure your spoken answer :**\nDefine binary search. Explain the algorithm. Mention its requirement of sorted data. Give iterative and recursive implementations.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss lower bound and upper bound variants."],
  ["Software Engineering", "Explain quicksort and its complexity.", "quicksort", "Explain quicksort.", "**Direct answer :**\nQuicksort is a divide-and-conquer sorting algorithm that picks a pivot, partitions the array into elements less and greater than pivot, and recursively sorts partitions. Average-case O(n log n), worst-case O(n^2) (unbalanced pivot).\n\nKey points to remember:\n- Choose pivot (commonly median-of-three).\n- Partition: place pivot in correct position, all smaller on left, larger on right.\n- Recursively sort left and right.\n- In-place sorting, not stable.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of efficient sorting algorithms.\n\n**Breaking it down :**\n- Choose pivot (commonly median-of-three).\n- Partition: place pivot in correct position, all smaller on left, larger on right.\n- Recursively sort left and right.\n- In-place sorting, not stable.\n\n**How to structure your spoken answer :**\nDefine quicksort. Explain the process. Discuss pivot selection and its impact on complexity. Mention optimizations (randomized pivot).\n\n**Follow-up angle to anticipate :**\nBe ready to implement partition and discuss worst-case scenarios."],
  ["Software Engineering", "Explain mergesort and its complexity.", "mergesort", "Explain mergesort.", "**Direct answer :**\nMergesort is a divide-and-conquer sorting algorithm that divides the array into halves, sorts each half, and merges the sorted halves. Complexity: O(n log n) in all cases, space O(n).\n\nKey points to remember:\n- Recursively split until single elements.\n- Merge: combine two sorted subarrays by comparing front elements.\n- Stable and well-suited for linked lists.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of stable sorting and external sorting.\n\n**Breaking it down :**\n- Recursively split until single elements.\n- Merge: combine two sorted subarrays by comparing front elements.\n- Stable and well-suited for linked lists.\n\n**How to structure your spoken answer :**\nDefine mergesort. Explain the divide and merge steps. Discuss time and space complexity. Mention its use in external sorting.\n\n**Follow-up angle to anticipate :**\nBe ready to compare mergesort and quicksort."],
  ["Software Engineering", "What is the time complexity of bubble sort and selection sort?", "bubble-selection-complexity", "Explain bubble and selection sort.", "**Direct answer :**\nBoth have O(n^2) average and worst-case time complexity. Bubble sort repeatedly swaps adjacent elements; selection sort finds minimum and places at front. They are inefficient for large data.\n\nKey points to remember:\n- Bubble: O(n^2), O(n) best-case if optimized.\n- Selection: O(n^2) always, O(1) space.\n- Both are not stable (selection not stable).\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of basic sorting algorithms.\n\n**Breaking it down :**\n- Bubble: O(n^2), O(n) best-case if optimized.\n- Selection: O(n^2) always, O(1) space.\n- Both are not stable (selection not stable).\n\n**How to structure your spoken answer :**\nDefine both. Explain their mechanisms. Mention their inefficiency but simplicity. Give use cases for small datasets.\n\n**Follow-up angle to anticipate :**\nBe ready to explain how to optimize bubble sort."],
  ["Software Engineering", "What is the difference between stable and unstable sorting?", "stable-vs-unstable-sort", "Compare stable and unstable sort.", "**Direct answer :**\nA stable sort maintains the relative order of equal elements; an unstable sort does not. Mergesort is stable; quicksort is typically unstable.\n\nKey points to remember:\n- Stability is important when sorting by multiple keys.\n- Example: sorting by first name then last name; stable ensures original order preserved for ties.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of sorting properties.\n\n**Breaking it down :**\n- Stability is important when sorting by multiple keys.\n- Example: sorting by first name then last name; stable ensures original order preserved for ties.\n\n**How to structure your spoken answer :**\nDefine stable and unstable. Give examples of each. Explain when stability matters.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to make quicksort stable."],
  ["Software Engineering", "What is the complexity of linear search?", "linear-search", "Explain linear search.", "**Direct answer :**\nLinear search checks each element until found or end. Worst-case O(n), best-case O(1). Used on unsorted data.\n\nKey points to remember:\n- Iterate through array.\n- Compare each element.\n- Return index or -1.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of simple search algorithms.\n\n**Breaking it down :**\n- Iterate through array.\n- Compare each element.\n- Return index or -1.\n\n**How to structure your spoken answer :**\nDefine linear search. Explain its time complexity. Mention when to use it (small or unsorted lists).\n\n**Follow-up angle to anticipate :**\nBe ready to compare with binary search."],
  ["Software Engineering", "What is the difference between depth-first search (DFS) and breadth-first search (BFS)?", "dfs-vs-bfs", "Compare DFS and BFS.", "**Direct answer :**\nDFS goes deep along a branch before backtracking; uses stack (recursion). BFS explores neighbors level by level; uses queue. DFS is memory-efficient for deep graphs; BFS finds shortest path in unweighted graphs.\n\nKey points to remember:\n- DFS: stack, time O(V+E), space O(V).\n- BFS: queue, time O(V+E), space O(V).\n- DFS for connectivity, topological sort; BFS for shortest paths.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of graph traversal algorithms.\n\n**Breaking it down :**\n- DFS: stack, time O(V+E), space O(V).\n- BFS: queue, time O(V+E), space O(V).\n- DFS for connectivity, topological sort; BFS for shortest paths.\n\n**How to structure your spoken answer :**\nDefine both. Contrast approach, data structures, and use cases. Mention iterative vs recursive.\n\n**Follow-up angle to anticipate :**\nBe ready to implement both and discuss their applications."],
  ["Software Engineering", "What is Dijkstra's algorithm and its complexity?", "dijkstra", "Explain Dijkstra.", "**Direct answer :**\nDijkstra's algorithm finds the shortest path from a source to all vertices in a weighted graph with non-negative weights. It uses a priority queue. Complexity: O((V+E) log V) with binary heap.\n\nKey points to remember:\n- Initialize distances, source = 0.\n- Use min-heap; extract min, relax neighbors.\n- Works for non-negative weights.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of shortest path algorithms.\n\n**Breaking it down :**\n- Initialize distances, source = 0.\n- Use min-heap; extract min, relax neighbors.\n- Works for non-negative weights.\n\n**How to structure your spoken answer :**\nDefine Dijkstra. Explain the algorithm with heap. Discuss complexity. Mention its limitations (no negative weights).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss Bellman-Ford for negative weights."],
  ["Software Engineering", "What is Bellman-Ford algorithm?", "bellman-ford", "Explain Bellman-Ford.", "**Direct answer :**\nBellman-Ford computes shortest paths from a source to all vertices, handling negative weights. It runs O(VE) and can detect negative cycles.\n\nKey points to remember:\n- Relax all edges V-1 times.\n- After that, if any edge can still relax, negative cycle exists.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of graphs with negative weights.\n\n**Breaking it down :**\n- Relax all edges V-1 times.\n- After that, if any edge can still relax, negative cycle exists.\n\n**How to structure your spoken answer :**\nDefine Bellman-Ford. Explain its purpose and complexity. Contrast with Dijkstra.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss applications and how to detect negative cycles."],
  ["Software Engineering", "What is Floyd-Warshall algorithm?", "floyd-warshall", "Explain Floyd-Warshall.", "**Direct answer :**\nFloyd-Warshall finds all-pairs shortest paths in a weighted graph (can handle negative weights, but no negative cycles). It uses DP with O(V^3) time and O(V^2) space.\n\nKey points to remember:\n- Initialize distance matrix.\n- For each intermediate k, update dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of all-pairs shortest path.\n\n**Breaking it down :**\n- Initialize distance matrix.\n- For each intermediate k, update dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]).\n\n**How to structure your spoken answer :**\nDefine Floyd-Warshall. Explain the DP approach. Mention its time and space. When to use it (dense graphs).\n\n**Follow-up angle to anticipate :**\nBe ready to compare with running Dijkstra from each node."],
  ["Software Engineering", "What is the knapsack problem and its solution?", "knapsack", "Explain knapsack.", "**Direct answer :**\nThe 0/1 knapsack problem: given items with weights and values, maximize total value without exceeding capacity. Solved with DP: dp[i][w] = max(dp[i-1][w], dp[i-1][w-wi] + vi). Time O(nW), space O(nW) or O(W).\n\nKey points to remember:\n- DP table: rows items, columns capacities.\n- Transition: either skip or take item.\n- Can be optimized to 1D array.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your DP skills.\n\n**Breaking it down :**\n- DP table: rows items, columns capacities.\n- Transition: either skip or take item.\n- Can be optimized to 1D array.\n\n**How to structure your spoken answer :**\nDefine the problem. Explain DP recurrence. Discuss time and space optimization. Mention greedy doesn't work for 0/1.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss fractional knapsack and its greedy solution."],
  ["Software Engineering", "What is the longest common subsequence (LCS) problem?", "lcs", "Explain LCS.", "**Direct answer :**\nLCS finds the longest subsequence common to two strings. DP: if chars match, dp[i][j]=1+dp[i-1][j-1]; else max(dp[i-1][j], dp[i][j-1]). Time O(mn).\n\nKey points to remember:\n- Build DP table.\n- Reconstruct sequence by backtracking.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your DP and string processing skills.\n\n**Breaking it down :**\n- Build DP table.\n- Reconstruct sequence by backtracking.\n\n**How to structure your spoken answer :**\nDefine LCS. Explain DP recurrence. Give example. Discuss complexity and variants.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss edit distance."],
  ["Software Engineering", "What is the edit distance (Levenshtein distance)?", "edit-distance", "Explain edit distance.", "**Direct answer :**\nEdit distance is the minimum number of insertions, deletions, or substitutions to transform one string into another. DP: dp[i][j] = min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+cost).\n\nKey points to remember:\n- Cost 0 if chars equal, 1 otherwise.\n- Recurrence as above.\n- Time O(mn).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your DP and text similarity understanding.\n\n**Breaking it down :**\n- Cost 0 if chars equal, 1 otherwise.\n- Recurrence as above.\n- Time O(mn).\n\n**How to structure your spoken answer :**\nDefine edit distance. Explain DP. Mention applications: spell checking, diff.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss Damerau-Levenshtein (transpositions)."],
  ["Software Engineering", "What is the maximum subarray sum (Kadane's algorithm)?", "kadane", "Explain Kadane.", "**Direct answer :**\nKadane's algorithm finds the maximum sum of a contiguous subarray in O(n). It maintains current sum and max sum, resetting current when negative.\n\nKey points to remember:\n- current = max(element, current + element).\n- max = max(max, current).\n- Handles all negatives as well.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of greedy/DP.\n\n**Breaking it down :**\n- current = max(element, current + element).\n- max = max(max, current).\n- Handles all negatives as well.\n\n**How to structure your spoken answer :**\nDefine the problem. Explain Kadane's algorithm with example. Mention it's a classic DP problem.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss variations: maximum product subarray."],
  ["Software Engineering", "What is the two-pointer technique?", "two-pointer", "Explain two-pointer.", "**Direct answer :**\nTwo-pointer technique uses two indices to traverse a data structure, often to solve problems like finding pairs that sum to target, removing duplicates, or reversing. It reduces O(n^2) to O(n).\n\nKey points to remember:\n- Common patterns: opposite ends (sorted array pair sum), same direction (slow/fast for cycle detection).\n- Example: find pair sum in sorted array: left=0, right=n-1, adjust.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to optimize solutions using pointers.\n\n**Breaking it down :**\n- Common patterns: opposite ends (sorted array pair sum), same direction (slow/fast for cycle detection).\n- Example: find pair sum in sorted array: left=0, right=n-1, adjust.\n\n**How to structure your spoken answer :**\nDefine two-pointer. Explain common scenarios. Give examples. Mention its efficiency.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a solution using two-pointer for a specific problem."],
  ["Software Engineering", "What is the sliding window technique?", "sliding-window", "Explain sliding window.", "**Direct answer :**\nSliding window is used for problems involving subarrays/substrings with constraints. It maintains a window that expands/contracts, often with two pointers, to achieve O(n) time.\n\nKey points to remember:\n- Example: longest substring without repeating characters.\n- Expand right pointer, contract left when violation.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to handle linear time substring/subarray problems.\n\n**Breaking it down :**\n- Example: longest substring without repeating characters.\n- Expand right pointer, contract left when violation.\n\n**How to structure your spoken answer :**\nDefine sliding window. Explain its working with example. Mention its use in many string/array problems.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a specific sliding window problem."],
  ["Software Engineering", "What is the difference between greedy and dynamic programming?", "greedy-vs-dp", "Compare greedy and DP.", "**Direct answer :**\nGreedy makes locally optimal choices hoping for global optimum; DP explores all possibilities and uses overlapping subproblems. Greedy is faster but not always optimal; DP is optimal but slower.\n\nKey points to remember:\n- Greedy: no backtracking, assumes optimal substructure and greedy choice property.\n- DP: solves subproblems and combines, optimal substructure and overlapping subproblems.\n- Examples: greedy: coin change (with certain denominations), DP: 0/1 knapsack.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of algorithmic paradigms.\n\n**Breaking it down :**\n- Greedy: no backtracking, assumes optimal substructure and greedy choice property.\n- DP: solves subproblems and combines, optimal substructure and overlapping subproblems.\n- Examples: greedy: coin change (with certain denominations), DP: 0/1 knapsack.\n\n**How to structure your spoken answer :**\nDefine both. Contrast characteristics. Give examples of when each is applicable.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when greedy fails."],
  ["Software Engineering", "What is backtracking and when is it used?", "backtracking", "Explain backtracking.", "**Direct answer :**\nBacktracking is a brute-force search algorithm that incrementally builds candidates and abandons a candidate as soon as it fails to satisfy constraints. Used for combinatorial problems like N-Queens, Sudoku, permutations.\n\nKey points to remember:\n- Recursive approach.\n- At each step, choose a value; if valid, recurse; else backtrack.\n- Pruning can reduce time.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of exhaustive search and pruning.\n\n**Breaking it down :**\n- Recursive approach.\n- At each step, choose a value; if valid, recurse; else backtrack.\n- Pruning can reduce time.\n\n**How to structure your spoken answer :**\nDefine backtracking. Explain the process. Give examples. Mention its exponential worst-case.\n\n**Follow-up angle to anticipate :**\nBe ready to implement N-Queens or Sudoku solver."],
  ["Software Engineering", "What is the traveling salesman problem (TSP)?", "tsp", "Explain TSP.", "**Direct answer :**\nTSP is a classic NP-hard problem: find the shortest possible route that visits each city exactly once and returns to origin. It can be solved exactly with DP (Held-Karp) in O(n^2 2^n) or heuristics like nearest neighbor.\n\nKey points to remember:\n- Held-Karp DP: state mask and current city.\n- Heuristics: greedy, 2-opt.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of NP-hard problems and approximation.\n\n**Breaking it down :**\n- Held-Karp DP: state mask and current city.\n- Heuristics: greedy, 2-opt.\n\n**How to structure your spoken answer :**\nDefine TSP. Mention its complexity. Discuss exact and approximation approaches.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the DP solution."],
  ["Software Engineering", "What is a topological sort and its algorithm?", "topological-sort", "Explain topological sort.", "**Direct answer :**\nTopological sort orders vertices in a directed acyclic graph (DAG) such that for every edge u→v, u comes before v. Algorithms: DFS (postorder) and Kahn's algorithm (BFS with indegree).\n\nKey points to remember:\n- DFS: do DFS, add to stack after visiting all children; reverse stack.\n- Kahn: repeatedly remove vertices with indegree 0.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of DAGs and scheduling.\n\n**Breaking it down :**\n- DFS: do DFS, add to stack after visiting all children; reverse stack.\n- Kahn: repeatedly remove vertices with indegree 0.\n\n**How to structure your spoken answer :**\nDefine topological sort. Explain both algorithms. Mention applications: task scheduling, course prerequisites.\n\n**Follow-up angle to anticipate :**\nBe ready to detect cycles in a directed graph."],
  ["Software Engineering", "What is the time complexity of sorting algorithms?", "sorting-complexities", "Summarize sorting complexities.", "**Direct answer :**\n- Quick sort: O(n log n) avg, O(n^2) worst.\n- Merge sort: O(n log n) all cases.\n- Heap sort: O(n log n) all cases.\n- Bubble/Selection/Insertion: O(n^2) worst.\n- Counting/Radix: O(n+k) or O(d(n+k)) for integer keys.\n\nKey points to remember:\n- Stable vs unstable also matters.\n- In-place vs not.\n\nFor an interview, state the normal/average complexity first, then mention the worst case or important assumptions. Complexity depends on the implementation and the operation being measured, so always name those assumptions.\n\n**Why this is asked :**\nInterviewers ask this to check your overall knowledge of sorting.\n\n**Breaking it down :**\n- Stable vs unstable also matters.\n- In-place vs not.\n\n**How to structure your spoken answer :**\nList common sorts with complexities. Mention space and stability. Give guidance on choosing a sort.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss which sort to use in specific scenarios."],
  ["Software Engineering", "What is the difference between a divide-and-conquer and dynamic programming?", "divide-conquer-vs-dp", "Compare paradigms.", "**Direct answer :**\nBoth break problems into subproblems. Divide-and-conquer solves independent subproblems recursively (e.g., mergesort); DP solves overlapping subproblems and stores results (e.g., Fibonacci).\n\nKey points to remember:\n- D&C: subproblems don't overlap, no memoization.\n- DP: overlapping subproblems, memoization or tabulation.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of algorithmic strategies.\n\n**Breaking it down :**\n- D&C: subproblems don't overlap, no memoization.\n- DP: overlapping subproblems, memoization or tabulation.\n\n**How to structure your spoken answer :**\nDefine both. Contrast subproblem independence and storage. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to identify when to use each."],
  ["Software Engineering", "What is the NP-complete problem? Give examples.", "np-complete", "Explain NP-complete.", "**Direct answer :**\nNP-complete problems are decision problems for which a solution can be verified in polynomial time, but no polynomial-time algorithm is known. Examples: SAT, TSP decision, knapsack decision.\n\nKey points to remember:\n- NP: verifiable in polynomial time.\n- NP-hard: at least as hard as NP-complete.\n- P vs NP is unsolved.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your theoretical computer science knowledge.\n\n**Breaking it down :**\n- NP: verifiable in polynomial time.\n- NP-hard: at least as hard as NP-complete.\n- P vs NP is unsolved.\n\n**How to structure your spoken answer :**\nDefine NP-complete. Explain the relationship with NP, NP-hard. Give examples. Mention implications.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss reduction and approximation algorithms."],
  ["Software Engineering", "What is the difference between a greedy algorithm and a backtracking algorithm?", "greedy-vs-backtracking", "Compare greedy and backtracking.", "**Direct answer :**\nGreedy makes a single pass, making locally optimal choices. Backtracking explores multiple possibilities, undoing choices when they fail. Greedy is fast but may not find optimal; backtracking finds optimal (exhaustive) but slow.\n\nKey points to remember:\n- Greedy: choice once, no undo.\n- Backtracking: choice then undo on failure.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your choice of algorithm for a problem.\n\n**Breaking it down :**\n- Greedy: choice once, no undo.\n- Backtracking: choice then undo on failure.\n\n**How to structure your spoken answer :**\nDefine both. Contrast their approach and outcome. Give examples: coin change with greedy vs DP/backtracking.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when greedy is applicable (matroid theory)."],
  ["Software Engineering", "What is the concept of Big-O notation?", "big-o", "Explain Big-O.", "**Direct answer :**\nBig-O notation describes an asymptotic upper bound on an algorithm's growth rate as the input size increases. In interviews, it is commonly used to describe worst-case growth, although formally Big-O itself is an upper-bound notation rather than a synonym for worst case. It ignores constant factors and lower-order terms when comparing growth.\n\nKey points to remember:\n- O(n) for linear; O(log n) for logarithmic; etc.\n- Used to compare scalability.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to analyze algorithm efficiency.\n\n**Breaking it down :**\n- O(n) for linear; O(log n) for logarithmic; etc.\n- Used to compare scalability.\n\n**How to structure your spoken answer :**\nDefine Big-O. Explain common complexities. Give examples. Mention that it's asymptotic.\n\n**Follow-up angle to anticipate :**\nBe ready to differentiate between Big-O, Big-Theta, Big-Omega."],

  // ==================== SYSTEM DESIGN (20) ====================
  ["Software Engineering", "What is scalability and how do you achieve it?", "scalability", "Explain scalability.", "**Direct answer :**\nScalability is the ability of a system to handle increased load by adding resources. Achieved via horizontal scaling (adding machines) or vertical scaling (upgrading hardware).\n\nKey points to remember:\n- Horizontal: distributed systems, load balancers, sharding.\n- Vertical: more CPU/RAM, but limited.\n- Also involves caching, asynchronous processing, database indexing.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your system design thinking.\n\n**Breaking it down :**\n- Horizontal: distributed systems, load balancers, sharding.\n- Vertical: more CPU/RAM, but limited.\n- Also involves caching, asynchronous processing, database indexing.\n\n**How to structure your spoken answer :**\nDefine scalability. Explain the two types. Mention techniques like load balancing, caching, and database sharding.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss trade-offs between horizontal and vertical scaling."],
  ["Software Engineering", "What is a load balancer and how does it work?", "load-balancer", "Explain load balancer.", "**Direct answer :**\nA load balancer distributes incoming network traffic across multiple servers to ensure no single server is overwhelmed. Algorithms: round-robin, least connections, IP hash, etc.\n\nKey points to remember:\n- Layer 4 (transport) or Layer 7 (application) load balancers.\n- Health checks to route only to healthy servers.\n- Can be hardware or software (HAProxy, Nginx).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of distributed systems.\n\n**Breaking it down :**\n- Layer 4 (transport) or Layer 7 (application) load balancers.\n- Health checks to route only to healthy servers.\n- Can be hardware or software (HAProxy, Nginx).\n\n**How to structure your spoken answer :**\nDefine load balancer. Explain its purpose and common algorithms. Mention health checks and session persistence.\n\n**Follow-up angle to anticipate :**\nBe ready to compare software vs hardware load balancers."],
  ["Software Engineering", "What is caching and what are its types?", "caching-types", "Explain caching.", "**Direct answer :**\nCaching stores frequently accessed data in fast storage to reduce latency and load on backend systems. Types: in-memory (Redis, Memcached), CDN, database query cache, browser cache.\n\nKey points to remember:\n- Cache eviction policies: LRU, LFU, TTL.\n- Write strategies: write-through, write-back, write-around.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of performance optimization.\n\n**Breaking it down :**\n- Cache eviction policies: LRU, LFU, TTL.\n- Write strategies: write-through, write-back, write-around.\n\n**How to structure your spoken answer :**\nDefine caching. Explain benefits. List types. Discuss eviction policies and trade-offs.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss cache consistency and invalidation."],
  ["Software Engineering", "What is CDN and why is it used?", "cdn", "Explain CDN.", "**Direct answer :**\nA CDN (Content Delivery Network) is a network of geographically distributed servers that deliver content (static assets) to users from the nearest edge location. It reduces latency and offloads origin servers.\n\nKey points to remember:\n- Edge servers cache static content.\n- DNS routing directs users to nearest edge.\n- Used for images, videos, CSS, JS.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of global content delivery.\n\n**Breaking it down :**\n- Edge servers cache static content.\n- DNS routing directs users to nearest edge.\n- Used for images, videos, CSS, JS.\n\n**How to structure your spoken answer :**\nDefine CDN. Explain how it works. List benefits: lower latency, high availability, DDoS protection.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss cache invalidation on CDN."],
  ["Software Engineering", "What is a database index and why is it used?", "database-index", "Explain index.", "**Direct answer :**\nA database index is a data structure that improves the speed of data retrieval operations on a table at the cost of additional writes and storage. Common types: B-tree, hash, bitmap.\n\nKey points to remember:\n- B-tree index supports range queries.\n- Hash index supports equality.\n- Indexes on foreign keys improve join performance.\n- Over-indexing can slow writes.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of database optimization.\n\n**Breaking it down :**\n- B-tree index supports range queries.\n- Hash index supports equality.\n- Indexes on foreign keys improve join performance.\n- Over-indexing can slow writes.\n\n**How to structure your spoken answer :**\nDefine index. Explain its purpose. Discuss types and trade-offs. Mention when to use/avoid indexes.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss composite indexes and covering indexes."],
  ["Software Engineering", "What is database sharding and its pros/cons?", "sharding", "Explain sharding.", "**Direct answer :**\nSharding is horizontal partitioning of data across multiple databases or nodes. Each shard holds a subset of data. Pros: scalability, performance. Cons: complexity, cross-shard queries, rebalancing.\n\nKey points to remember:\n- Shard key selection is critical (e.g., user ID).\n- Range sharding vs hash sharding.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of distributed database design.\n\n**Breaking it down :**\n- Shard key selection is critical (e.g., user ID).\n- Range sharding vs hash sharding.\n\n**How to structure your spoken answer :**\nDefine sharding. Explain why it's needed. Discuss advantages and challenges. Give examples of shard key strategies.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss sharding vs replication."],
  ["Software Engineering", "What is the difference between vertical and horizontal scaling?", "vertical-vs-horizontal-scaling", "Compare scaling methods.", "**Direct answer :**\nVertical scaling adds resources (CPU/RAM) to a single machine; horizontal scaling adds more machines. Vertical is limited by hardware; horizontal is more scalable and fault-tolerant.\n\nKey points to remember:\n- Vertical: simpler, no distributed complexity; but single point of failure.\n- Horizontal: distributed, requires load balancing, but can scale indefinitely.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of scaling strategies.\n\n**Breaking it down :**\n- Vertical: simpler, no distributed complexity; but single point of failure.\n- Horizontal: distributed, requires load balancing, but can scale indefinitely.\n\n**How to structure your spoken answer :**\nDefine both. Contrast pros and cons. Give use cases.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to choose each."],
  ["Software Engineering", "What is a message queue and when to use it?", "message-queue", "Explain message queue.", "**Direct answer :**\nA message queue is a component that enables asynchronous communication between services by storing messages until they are processed. Used for decoupling, load leveling, and reliability. Examples: RabbitMQ, Kafka, SQS.\n\nKey points to remember:\n- Producer sends messages to queue.\n- Consumer processes messages.\n- Provides delivery guarantees, ordering, and persistence.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of distributed communication.\n\n**Breaking it down :**\n- Producer sends messages to queue.\n- Consumer processes messages.\n- Provides delivery guarantees, ordering, and persistence.\n\n**How to structure your spoken answer :**\nDefine message queue. Explain its benefits. Give use cases: task queues, event-driven architecture. Mention popular implementations.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss differences between message queue and event streaming."],
  ["Software Engineering", "What is the CAP theorem?", "cap-theorem", "Explain CAP theorem.", "**Direct answer :**\nThe CAP theorem says that, during a network partition in a distributed system, you cannot simultaneously guarantee both strong consistency and availability for every request. The three properties are consistency, availability, and partition tolerance. Partition tolerance is not simply a feature you can switch off in a distributed system; when a partition occurs, the practical choice is which guarantee to sacrifice.\n\nKey points to remember:\n- Consistency: all nodes see same data at same time.\n- Availability: every request receives a response.\n- Partition tolerance: system continues despite network partitions.\n- Examples: CP (HBase), AP (Cassandra), CA (not possible in distributed).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of distributed system trade-offs.\n\n**Breaking it down :**\n- Consistency: all nodes see same data at same time.\n- Availability: every request receives a response.\n- Partition tolerance: system continues despite network partitions.\n- Examples: CP (HBase), AP (Cassandra), CA (not possible in distributed).\n\n**How to structure your spoken answer :**\nDefine CAP. Explain each property. Discuss trade-offs. Mention real-world examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss PACELC as an extension."],
  ["Software Engineering", "What is the difference between SQL and NoSQL databases?", "sql-vs-nosql", "Compare SQL and NoSQL.", "**Direct answer :**\nSQL databases are relational systems that organize data into tables and provide SQL plus strong transactional and integrity features. NoSQL is a broad category that includes document, key-value, wide-column, and graph databases; their consistency, transaction, schema, and scaling characteristics vary by product. The right choice depends on access patterns, relationships, consistency requirements, transaction boundaries, scale, and operational needs rather than a blanket claim that one category is better.\n\nKey points to remember:\n- SQL: structured, join-intensive, vertical scaling.\n- NoSQL: unstructured, horizontal scaling, high availability.\n- Use cases: SQL for banking, NoSQL for social media.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to choose a database for requirements.\n\n**Breaking it down :**\n- SQL: structured, join-intensive, vertical scaling.\n- NoSQL: unstructured, horizontal scaling, high availability.\n- Use cases: SQL for banking, NoSQL for social media.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by schema, scaling, transactions, and use cases. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss specific NoSQL types and their use cases."],
  ["Software Engineering", "What is a microservice architecture?", "microservices", "Explain microservices.", "**Direct answer :**\nMicroservices architecture structures an application as a collection of loosely coupled, independently deployable services, each owning its own data and business domain. They communicate via APIs or messaging.\n\nKey points to remember:\n- Each service focuses on a business capability.\n- Independent deployment, scaling, and development.\n- Challenges: distributed transactions, network latency, monitoring.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of modern software architecture.\n\n**Breaking it down :**\n- Each service focuses on a business capability.\n- Independent deployment, scaling, and development.\n- Challenges: distributed transactions, network latency, monitoring.\n\n**How to structure your spoken answer :**\nDefine microservices. List benefits. Mention challenges. Compare with monolith.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss service discovery, API gateway, and data consistency."],
  ["Software Engineering", "What is the difference between monolithic and microservice architecture?", "monolith-vs-microservices", "Compare architectures.", "**Direct answer :**\nMonolith has a single codebase and deployment unit; microservices are split into multiple independent services. Monolith is simpler to develop initially, but harder to scale and maintain; microservices offer flexibility and resilience but add complexity.\n\nKey points to remember:\n- Monolith: single deployable artifact, simpler testing, but all changes affect whole system.\n- Microservices: independent services, technology heterogeneity, but distributed overhead.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of architectural trade-offs.\n\n**Breaking it down :**\n- Monolith: single deployable artifact, simpler testing, but all changes affect whole system.\n- Microservices: independent services, technology heterogeneity, but distributed overhead.\n\n**How to structure your spoken answer :**\nDefine both. Compare by development, deployment, scaling, and complexity. Give examples of when to choose each.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss migration strategies."],
  ["Software Engineering", "What is an API gateway?", "api-gateway", "Explain API gateway.", "**Direct answer :**\nAn API gateway is a single entry point for all client requests in a microservices architecture. It handles routing, authentication, rate limiting, caching, and logging. It shields clients from service internals.\n\nKey points to remember:\n- Routes requests to appropriate services.\n- May aggregate responses.\n- Implements cross-cutting concerns.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of microservices infrastructure.\n\n**Breaking it down :**\n- Routes requests to appropriate services.\n- May aggregate responses.\n- Implements cross-cutting concerns.\n\n**How to structure your spoken answer :**\nDefine API gateway. List its responsibilities. Mention examples (Kong, Spring Cloud Gateway).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between API gateway and load balancer."],
  ["Software Engineering", "What is the difference between stateful and stateless services?", "stateful-vs-stateless", "Compare stateful and stateless.", "**Direct answer :**\nStateful services maintain client state (e.g., session) across requests; stateless services do not. Stateless are easier to scale horizontally; stateful require sticky sessions or shared storage.\n\nKey points to remember:\n- Stateless: each request can be handled by any instance, no dependency on previous requests. Easier to scale.\n- Stateful: need to keep session data; can be handled by external storage (Redis) or sticky sessions.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of distributed system design.\n\n**Breaking it down :**\n- Stateless: each request can be handled by any instance, no dependency on previous requests. Easier to scale.\n- Stateful: need to keep session data; can be handled by external storage (Redis) or sticky sessions.\n\n**How to structure your spoken answer :**\nDefine both. Explain advantages and challenges. Give examples: REST APIs are stateless; user sessions are stateful.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to achieve statelessness (e.g., JWT)."],
  ["Software Engineering", "What is a circuit breaker in system design?", "circuit-breaker", "Explain circuit breaker.", "**Direct answer :**\nA circuit breaker pattern prevents a system from repeatedly trying to execute an operation that is likely to fail. It monitors failures and opens the circuit to stop calls, and later tests to see if the service is recovered.\n\nKey points to remember:\n- States: closed (normal), open (fail fast), half-open (test recovery).\n- Prevents cascading failures and timeouts.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of resilience patterns.\n\n**Breaking it down :**\n- States: closed (normal), open (fail fast), half-open (test recovery).\n- Prevents cascading failures and timeouts.\n\n**How to structure your spoken answer :**\nDefine circuit breaker. Explain its states and transition. Give use cases in microservices.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss implementation with libraries like Resilience4j."],
  ["Software Engineering", "What is a rate limiter and why is it used?", "rate-limiter", "Explain rate limiter.", "**Direct answer :**\nA rate limiter controls the number of requests a client can make in a given time window. It prevents abuse, ensures fair usage, and protects system resources. Algorithms: token bucket, leaky bucket, fixed window, sliding window.\n\nKey points to remember:\n- Token bucket: refills at a rate; burst capacity.\n- Sliding window: more accurate than fixed.\n- Often implemented at API gateway or middleware.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of API protection.\n\n**Breaking it down :**\n- Token bucket: refills at a rate; burst capacity.\n- Sliding window: more accurate than fixed.\n- Often implemented at API gateway or middleware.\n\n**How to structure your spoken answer :**\nDefine rate limiter. Explain its purpose. Describe common algorithms. Mention trade-offs.\n\n**Follow-up angle to anticipate :**\nBe ready to implement a token bucket algorithm."],
  ["Software Engineering", "What is the difference between a forward proxy and a reverse proxy?", "forward-vs-reverse-proxy", "Compare proxies.", "**Direct answer :**\nA forward proxy sits between client and internet, forwarding requests on behalf of clients (e.g., for anonymity). A reverse proxy sits between internet and servers, forwarding requests to backend servers (e.g., for load balancing, caching).\n\nKey points to remember:\n- Forward proxy: client-side, hides client identity.\n- Reverse proxy: server-side, hides server identity, provides load balancing, SSL termination.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of networking and architecture.\n\n**Breaking it down :**\n- Forward proxy: client-side, hides client identity.\n- Reverse proxy: server-side, hides server identity, provides load balancing, SSL termination.\n\n**How to structure your spoken answer :**\nDefine both. Contrast their position and purpose. Give examples: Squid (forward), Nginx (reverse).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss use cases for each."],
  ["Software Engineering", "What is the difference between a synchronous and asynchronous communication in distributed systems?", "sync-vs-async-distributed", "Compare sync and async.", "**Direct answer :**\nSynchronous communication means the caller normally waits for the operation to complete or for a response before continuing. Asynchronous communication lets the caller continue without waiting for the consumer to finish, commonly using queues, events, or callbacks. Asynchronous does not automatically mean faster or non-blocking at every layer; it mainly changes coupling, timing, and failure-handling behavior.\n\nKey points to remember:\n- Sync: HTTP REST, RPC; simple but can cause timeouts.\n- Async: messaging, event-driven; more scalable but complex.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of communication patterns.\n\n**Breaking it down :**\n- Sync: HTTP REST, RPC; simple but can cause timeouts.\n- Async: messaging, event-driven; more scalable but complex.\n\n**How to structure your spoken answer :**\nDefine both. Contrast with examples. Discuss when to use each.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss eventual consistency."],
  ["Software Engineering", "What is a distributed transaction and how is it handled?", "distributed-transaction", "Explain distributed transaction.", "**Direct answer :**\nA distributed transaction spans multiple services/resources. It's challenging due to CAP theorem. Solutions: two-phase commit (2PC) for strong consistency, or Saga pattern for eventual consistency with compensating actions.\n\nKey points to remember:\n- 2PC: coordinator prepares all participants then commits; blocking and not always available.\n- Saga: sequence of local transactions; if one fails, compensating transactions rollback.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of data consistency in microservices.\n\n**Breaking it down :**\n- 2PC: coordinator prepares all participants then commits; blocking and not always available.\n- Saga: sequence of local transactions; if one fails, compensating transactions rollback.\n\n**How to structure your spoken answer :**\nDefine distributed transaction. Explain challenges. Discuss 2PC and Saga. Mention that Saga is more common in microservices.\n\n**Follow-up angle to anticipate :**\nBe ready to describe a Saga implementation."],
  ["Software Engineering", "What is the difference between a database and a data warehouse?", "db-vs-data-warehouse", "Compare database and data warehouse.", "**Direct answer :**\nA database is an OLTP system for transactional processing (CRUD). A data warehouse is an OLAP system for analytics and reporting, storing historical data from multiple sources.\n\nKey points to remember:\n- Database: normalized, row-oriented, fast writes.\n- Data warehouse: denormalized, columnar storage, optimized for read-heavy queries.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of data storage systems.\n\n**Breaking it down :**\n- Database: normalized, row-oriented, fast writes.\n- Data warehouse: denormalized, columnar storage, optimized for read-heavy queries.\n\n**How to structure your spoken answer :**\nDefine both. Contrast purpose, schema, and usage. Give examples: MySQL vs Snowflake.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss ETL processes."],

  // ==================== OBJECT-ORIENTED PROGRAMMING (15) ====================
  ["Software Engineering", "What are the four pillars of OOP?", "oop-pillars", "Explain OOP pillars.", "**Direct answer :**\nThe four pillars are: Encapsulation (hiding internal state), Inheritance (subclassing), Polymorphism (many forms), and Abstraction (hiding complexity).\n\nKey points to remember:\n- Encapsulation: bundle data and methods, restrict access.\n- Inheritance: create class hierarchies, reuse code.\n- Polymorphism: same interface, different implementations (overriding).\n- Abstraction: provide simple interfaces, hide details.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your foundational OOP knowledge.\n\n**Breaking it down :**\n- Encapsulation: bundle data and methods, restrict access.\n- Inheritance: create class hierarchies, reuse code.\n- Polymorphism: same interface, different implementations (overriding).\n- Abstraction: provide simple interfaces, hide details.\n\n**How to structure your spoken answer :**\nList and define each. Give examples. Mention how they promote modularity and reusability.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss composition over inheritance."],
  ["Software Engineering", "What is the difference between abstraction and encapsulation?", "abstraction-vs-encapsulation", "Compare abstraction and encapsulation.", "**Direct answer :**\nAbstraction focuses on what an object does (interface); encapsulation focuses on how it does it (implementation details). Abstraction hides complexity; encapsulation hides data.\n\nKey points to remember:\n- Abstraction: using abstract classes/interfaces to define contracts.\n- Encapsulation: using private fields and public getters/setters.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of these often-confused concepts.\n\n**Breaking it down :**\n- Abstraction: using abstract classes/interfaces to define contracts.\n- Encapsulation: using private fields and public getters/setters.\n\n**How to structure your spoken answer :**\nDefine both. Contrast purpose and implementation. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how they work together."],
  ["Software Engineering", "What is inheritance and its types?", "inheritance-types", "Explain inheritance.", "**Direct answer :**\nInheritance allows a class to acquire properties and methods from a parent class. Types: single (one parent), multiple (multiple parents, not supported in Java/C#), multilevel, hierarchical, and hybrid.\n\nKey points to remember:\n- Single: one child extends one parent.\n- Multilevel: chain of inheritance.\n- Hierarchical: multiple children from one parent.\n- Multiple: not allowed in many languages (diamond problem).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of class hierarchies.\n\n**Breaking it down :**\n- Single: one child extends one parent.\n- Multilevel: chain of inheritance.\n- Hierarchical: multiple children from one parent.\n- Multiple: not allowed in many languages (diamond problem).\n\n**How to structure your spoken answer :**\nDefine inheritance. List types with examples. Mention the diamond problem.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss composition as an alternative."],
  ["Software Engineering", "What is polymorphism and its types?", "polymorphism-types", "Explain polymorphism.", "**Direct answer :**\nPolymorphism means 'many forms'. Compile-time (method overloading) and runtime (method overriding). Runtime polymorphism uses dynamic binding to call the correct method based on object type.\n\nKey points to remember:\n- Overloading: same method name, different parameters (compile-time).\n- Overriding: subclass provides specific implementation (runtime).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of dynamic behavior.\n\n**Breaking it down :**\n- Overloading: same method name, different parameters (compile-time).\n- Overriding: subclass provides specific implementation (runtime).\n\n**How to structure your spoken answer :**\nDefine polymorphism. Explain the two types. Give examples. Mention its role in flexible design.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss method overloading vs overriding."],
  ["Software Engineering", "What is the difference between overloading and overriding?", "overloading-vs-overriding", "Compare overloading and overriding.", "**Direct answer :**\nOverloading occurs within the same class (or subclass) with different parameters; overriding occurs in a subclass to replace a parent method with the same signature. Overloading is compile-time; overriding is runtime.\n\nKey points to remember:\n- Overloading: method name same, parameters differ; return type may differ.\n- Overriding: method signature identical; must have same return type (covariant allowed); cannot reduce access.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of method resolution.\n\n**Breaking it down :**\n- Overloading: method name same, parameters differ; return type may differ.\n- Overriding: method signature identical; must have same return type (covariant allowed); cannot reduce access.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by location, signature, and binding time. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the use of `@Override` annotation."],
  ["Software Engineering", "What is an abstract class vs an interface?", "abstract-vs-interface", "Compare abstract class and interface.", "**Direct answer :**\nAn abstract class can have state (fields) and concrete methods; an interface is a contract with only abstract methods (before Java 8) and can have default/static methods now. Abstract classes are for single inheritance; interfaces allow multiple inheritance.\n\nKey points to remember:\n- Abstract class: can have constructors, fields, and method implementations.\n- Interface: no state (except static final), multiple implementation.\n- Choose abstract class for common base; interface for capability.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your design decisions.\n\n**Breaking it down :**\n- Abstract class: can have constructors, fields, and method implementations.\n- Interface: no state (except static final), multiple implementation.\n- Choose abstract class for common base; interface for capability.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by features and usage. Give examples. Mention Java 8+ changes.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to use each."],
  ["Software Engineering", "What is composition over inheritance?", "composition-over-inheritance", "Explain composition.", "**Direct answer :**\nComposition over inheritance is a principle that favors assembling objects using other objects (has-a relationship) rather than extending classes (is-a). It promotes flexibility, avoids fragile base class issues, and enables more modular design.\n\nKey points to remember:\n- Inheritance: tight coupling, brittle hierarchies.\n- Composition: uses interfaces and delegations, more adaptable.\n- Example: `Car` has an `Engine` rather than `Car extends Engine`.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of design principles.\n\n**Breaking it down :**\n- Inheritance: tight coupling, brittle hierarchies.\n- Composition: uses interfaces and delegations, more adaptable.\n- Example: `Car` has an `Engine` rather than `Car extends Engine`.\n\n**How to structure your spoken answer :**\nDefine composition. Explain its advantages over inheritance. Give an example. Mention the principle 'favor composition over inheritance'.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the decorator pattern as an example."],
  ["Software Engineering", "What is the SOLID principles?", "solid", "Explain SOLID.", "**Direct answer :**\nSOLID is an acronym for five design principles: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion. They help create maintainable and scalable software.\n\nKey points to remember:\n- S: a class should have only one reason to change.\n- O: classes should be open for extension, closed for modification.\n- L: subtypes must be substitutable for their base types.\n- I: many client-specific interfaces are better than one general-purpose.\n- D: depend on abstractions, not concretions.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of object-oriented design.\n\n**Breaking it down :**\n- S: a class should have only one reason to change.\n- O: classes should be open for extension, closed for modification.\n- L: subtypes must be substitutable for their base types.\n- I: many client-specific interfaces are better than one general-purpose.\n- D: depend on abstractions, not concretions.\n\n**How to structure your spoken answer :**\nList and briefly explain each principle. Give examples. Mention they are guidelines, not strict rules.\n\n**Follow-up angle to anticipate :**\nBe ready to dive deeper into one principle (e.g., Liskov)."],
  ["Software Engineering", "What is the Single Responsibility Principle?", "srp", "Explain SRP.", "**Direct answer :**\nThe Single Responsibility Principle states that a class should have only one reason to change, meaning it should have only one job or responsibility. This improves cohesion and reduces coupling.\n\nKey points to remember:\n- Example: A class that handles both data access and business logic violates SRP.\n- Split into DAO and service classes.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to design focused classes.\n\n**Breaking it down :**\n- Example: A class that handles both data access and business logic violates SRP.\n- Split into DAO and service classes.\n\n**How to structure your spoken answer :**\nDefine SRP. Explain its importance. Give an example of violation and solution.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to identify responsibilities."],
  ["Software Engineering", "What is the Open/Closed Principle?", "ocp", "Explain OCP.", "**Direct answer :**\nThe Open/Closed Principle states that classes should be open for extension but closed for modification. You should be able to add new functionality without changing existing code, typically using inheritance or composition.\n\nKey points to remember:\n- Achieved via abstract base classes or interfaces.\n- New behavior added via new subclasses or implementations.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of extensibility.\n\n**Breaking it down :**\n- Achieved via abstract base classes or interfaces.\n- New behavior added via new subclasses or implementations.\n\n**How to structure your spoken answer :**\nDefine OCP. Explain how to achieve it. Give an example: adding a new payment method without changing the existing payment processing logic.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the strategy pattern as an implementation."],
  ["Software Engineering", "What is the Liskov Substitution Principle?", "lsp", "Explain LSP.", "**Direct answer :**\nThe Liskov Substitution Principle states that objects of a superclass should be replaceable with objects of a subclass without affecting the correctness of the program. Subtypes must honor the contract of the base type.\n\nKey points to remember:\n- If `Square` extends `Rectangle`, setting width should not break the expected behavior.\n- Violation: overriding methods to weaken preconditions or strengthen postconditions.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of inheritance contracts.\n\n**Breaking it down :**\n- If `Square` extends `Rectangle`, setting width should not break the expected behavior.\n- Violation: overriding methods to weaken preconditions or strengthen postconditions.\n\n**How to structure your spoken answer :**\nDefine LSP. Explain its implications. Give a classic example (Rectangle/Square).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to avoid LSP violations (composition)."],
  ["Software Engineering", "What is the Interface Segregation Principle?", "isp", "Explain ISP.", "**Direct answer :**\nThe Interface Segregation Principle states that clients should not be forced to depend on interfaces they do not use. It's better to have multiple, smaller, focused interfaces than one large, general-purpose one.\n\nKey points to remember:\n- Split a fat interface into several role-specific interfaces.\n- Example: `Worker` interface split into `Workable` and `Eatable`.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your ability to design cohesive interfaces.\n\n**Breaking it down :**\n- Split a fat interface into several role-specific interfaces.\n- Example: `Worker` interface split into `Workable` and `Eatable`.\n\n**How to structure your spoken answer :**\nDefine ISP. Explain the benefits: decoupling, easier implementation. Give an example.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between ISP and SRP."],
  ["Software Engineering", "What is the Dependency Inversion Principle?", "dip", "Explain DIP.", "**Direct answer :**\nThe Dependency Inversion Principle states that high-level modules should not depend on low-level modules; both should depend on abstractions. Abstractions should not depend on details; details should depend on abstractions.\n\nKey points to remember:\n- Use interfaces to decouple.\n- Dependency injection is a common implementation.\n- Example: `Service` depends on `Repository` interface, not concrete `MySQLRepository`.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of dependency management.\n\n**Breaking it down :**\n- Use interfaces to decouple.\n- Dependency injection is a common implementation.\n- Example: `Service` depends on `Repository` interface, not concrete `MySQLRepository`.\n\n**How to structure your spoken answer :**\nDefine DIP. Explain its purpose. Give an example. Mention dependency injection as a means to achieve it.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss inversion of control containers."],
  ["Software Engineering", "What is encapsulation and how to achieve it?", "encapsulation", "Explain encapsulation.", "**Direct answer :**\nEncapsulation bundles data (fields) and methods that operate on that data into a single unit (class), and hides internal state using access modifiers (private, protected). It is achieved by making fields private and providing public getters/setters.\n\nKey points to remember:\n- Protects data integrity.\n- Allows controlled access via methods.\n- Reduces coupling.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of data hiding.\n\n**Breaking it down :**\n- Protects data integrity.\n- Allows controlled access via methods.\n- Reduces coupling.\n\n**How to structure your spoken answer :**\nDefine encapsulation. Explain how to implement it. Give an example. Mention its benefits.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the trade-offs of exposing getters/setters."],
  ["Software Engineering", "What is a design pattern? Give examples of creational, structural, behavioral.", "design-patterns", "Explain design patterns.", "**Direct answer :**\nDesign patterns are reusable solutions to common problems in software design. Creational: Singleton, Factory, Builder. Structural: Adapter, Decorator, Proxy. Behavioral: Observer, Strategy, Command.\n\nKey points to remember:\n- Creational: object creation mechanisms.\n- Structural: compose classes/objects.\n- Behavioral: communication between objects.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of proven design solutions.\n\n**Breaking it down :**\n- Creational: object creation mechanisms.\n- Structural: compose classes/objects.\n- Behavioral: communication between objects.\n\n**How to structure your spoken answer :**\nDefine design patterns. List categories with a few examples. Mention their benefits: reusability, maintainability.\n\n**Follow-up angle to anticipate :**\nBe ready to explain a specific pattern in detail."],

  // ==================== DATABASES (10) ====================
  ["Software Engineering", "What is a transaction and its properties (ACID)?", "acid", "Explain ACID.", "**Direct answer :**\nACID stands for Atomicity (all or nothing), Consistency (valid state), Isolation (concurrent execution doesn't affect each other), Durability (changes persist). These properties ensure reliable database transactions.\n\nKey points to remember:\n- Atomicity: transaction either fully completes or fully rolls back.\n- Consistency: transaction brings database from one valid state to another.\n- Isolation: concurrent transactions appear serializable.\n- Durability: committed transactions survive failures.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of database reliability.\n\n**Breaking it down :**\n- Atomicity: transaction either fully completes or fully rolls back.\n- Consistency: transaction brings database from one valid state to another.\n- Isolation: concurrent transactions appear serializable.\n- Durability: committed transactions survive failures.\n\n**How to structure your spoken answer :**\nDefine each property. Explain their importance. Give examples. Mention isolation levels.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss different isolation levels and their trade-offs."],
  ["Software Engineering", "What are the different isolation levels in SQL?", "isolation-levels", "Explain isolation levels.", "**Direct answer :**\nIsolation levels define the degree to which transactions are isolated from each other. Read Uncommitted (dirty reads), Read Committed (no dirty reads), Repeatable Read (consistent reads), Serializable (strongest).\n\nKey points to remember:\n- Read Uncommitted: allows dirty reads.\n- Read Committed: prevents dirty reads but allows non-repeatable reads.\n- Repeatable Read: ensures same row read same within transaction.\n- Serializable: prevents all anomalies but reduces concurrency.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of concurrency control.\n\n**Breaking it down :**\n- Read Uncommitted: allows dirty reads.\n- Read Committed: prevents dirty reads but allows non-repeatable reads.\n- Repeatable Read: ensures same row read same within transaction.\n- Serializable: prevents all anomalies but reduces concurrency.\n\n**How to structure your spoken answer :**\nList levels. Explain each with anomalies they prevent. Mention trade-offs.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss phantom reads."],
  ["Software Engineering", "What is a primary key and foreign key?", "primary-foreign-key", "Explain keys.", "**Direct answer :**\nA primary key uniquely identifies a row in a table; it must be unique and not null. A foreign key is a field in one table that refers to the primary key of another table, enforcing referential integrity.\n\nKey points to remember:\n- Primary key: uniquely identifies each record.\n- Foreign key: links tables, establishes relationships.\n- Both are essential for normalization.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your basic database design knowledge.\n\n**Breaking it down :**\n- Primary key: uniquely identifies each record.\n- Foreign key: links tables, establishes relationships.\n- Both are essential for normalization.\n\n**How to structure your spoken answer :**\nDefine both. Explain their roles. Give an example: Orders table has customer_id foreign key referencing Customers table.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss composite keys."],
  ["Software Engineering", "What is a normalized database and why normalize?", "normalization", "Explain normalization.", "**Direct answer :**\nNormalization is the process of organizing data to reduce redundancy and improve integrity. It involves dividing tables into smaller related tables and defining relationships. Normal forms (1NF, 2NF, 3NF, BCNF) are used.\n\nKey points to remember:\n- 1NF: atomic values, no repeating groups.\n- 2NF: no partial dependency on composite key.\n- 3NF: no transitive dependency.\n- Benefits: reduces anomalies, saves space.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your schema design skills.\n\n**Breaking it down :**\n- 1NF: atomic values, no repeating groups.\n- 2NF: no partial dependency on composite key.\n- 3NF: no transitive dependency.\n- Benefits: reduces anomalies, saves space.\n\n**How to structure your spoken answer :**\nDefine normalization. Explain the normal forms. Mention trade-offs with denormalization for performance.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss denormalization and when to use it."],
  ["Software Engineering", "What is a SQL join and its types?", "sql-joins", "Explain joins.", "**Direct answer :**\nJoins combine rows from two or more tables based on related columns. Types: INNER JOIN, LEFT JOIN, RIGHT JOIN, FULL JOIN, and CROSS JOIN.\n\nKey points to remember:\n- INNER: returns only matching rows.\n- LEFT: all from left, matching from right.\n- RIGHT: all from right, matching from left.\n- FULL: all rows from both, filling nulls.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your SQL query skills.\n\n**Breaking it down :**\n- INNER: returns only matching rows.\n- LEFT: all from left, matching from right.\n- RIGHT: all from right, matching from left.\n- FULL: all rows from both, filling nulls.\n\n**How to structure your spoken answer :**\nDefine joins. List types with explanations. Give examples. Mention that joins are used in relational databases.\n\n**Follow-up angle to anticipate :**\nBe ready to write a query using joins."],
  ["Software Engineering", "What is a stored procedure and its advantages?", "stored-procedure", "Explain stored procedure.", "**Direct answer :**\nA stored procedure is a named program defined and executed by a database system. It can accept parameters and contain SQL plus database-specific procedural logic. Stored procedures can centralize data-side operations, enforce controlled access patterns, and reduce application/database round trips in some workloads, but they can also increase vendor coupling and require careful versioning, testing, and performance management. Do not assume that every database precompiles procedures in a way that automatically makes them faster.\n\nKey points to remember:\n- Can accept parameters.\n- Can contain logic (loops, conditions).\n- Cons: vendor-specific, harder to version.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of database programming.\n\n**Breaking it down :**\n- Can accept parameters.\n- Can contain logic (loops, conditions).\n- Cons: vendor-specific, harder to version.\n\n**How to structure your spoken answer :**\nDefine stored procedure. List benefits and drawbacks. Give a use case.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss functions vs procedures."],
  ["Software Engineering", "What is the difference between `DELETE` and `TRUNCATE`?", "delete-vs-truncate", "Compare DELETE and TRUNCATE.", "**Direct answer :**\n`DELETE` is a row-level DML operation that can remove selected rows with a `WHERE` clause, while `TRUNCATE` is generally a DDL-style operation that removes all rows from a table with database-specific transactional and logging behavior. Exact rollback, trigger, identity/sequence, locking, and performance behavior depends on the database engine, so you should not claim that `TRUNCATE` is universally non-rollbackable.\n\nKey points to remember:\n- DELETE: DML, where clause possible, slower, logs each row.\n- TRUNCATE: DDL, no where, faster, minimal logging.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of data removal.\n\n**Breaking it down :**\n- DELETE: DML, where clause possible, slower, logs each row.\n- TRUNCATE: DDL, no where, faster, minimal logging.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by operation type, rollback, triggers, and speed. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss `DROP` as well."],
  ["Software Engineering", "What is the difference between `UNION` and `UNION ALL`?", "union-vs-union-all", "Compare UNION and UNION ALL.", "**Direct answer :**\n`UNION` combines results from two queries and removes duplicates; `UNION ALL` does not remove duplicates, so it's faster.\n\nKey points to remember:\n- UNION: performs distinct sort; overhead.\n- UNION ALL: simply concatenates; use when duplicates are acceptable or not present.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of result set manipulation.\n\n**Breaking it down :**\n- UNION: performs distinct sort; overhead.\n- UNION ALL: simply concatenates; use when duplicates are acceptable or not present.\n\n**How to structure your spoken answer :**\nDefine both. Explain performance difference. Give use cases.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to use each."],
  ["Software Engineering", "What is a view in SQL?", "sql-view", "Explain view.", "**Direct answer :**\nA view is a virtual table based on the result of a SELECT query. It does not store data physically; it simplifies complex queries and provides security by restricting access to certain rows/columns.\n\nKey points to remember:\n- Can join multiple tables.\n- Can be updatable (under certain conditions).\n- Can be used to enforce row-level security.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of abstraction in databases.\n\n**Breaking it down :**\n- Can join multiple tables.\n- Can be updatable (under certain conditions).\n- Can be used to enforce row-level security.\n\n**How to structure your spoken answer :**\nDefine view. Explain its purpose and benefits. Give an example. Mention materialized views.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss materialized views vs views."],
  ["Software Engineering", "What is a database trigger?", "trigger", "Explain trigger.", "**Direct answer :**\nA trigger is a procedural code that automatically executes in response to certain events (INSERT, UPDATE, DELETE) on a table. Used for auditing, data validation, and maintaining complex integrity.\n\nKey points to remember:\n- BEFORE/AFTER trigger.\n- Can be row-level or statement-level.\n- Careful: can cause performance issues and hidden logic.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of automated database logic.\n\n**Breaking it down :**\n- BEFORE/AFTER trigger.\n- Can be row-level or statement-level.\n- Careful: can cause performance issues and hidden logic.\n\n**How to structure your spoken answer :**\nDefine trigger. Explain its use cases. Mention caveats.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss alternatives (application logic, stored procedures)."],

  // ==================== NETWORKING (10) ====================
  ["Software Engineering", "What is the OSI model and its layers?", "osi-model", "Explain OSI.", "**Direct answer :**\nThe OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation, Application. It standardizes network communication.\n\nKey points to remember:\n- Physical: bits, cables.\n- Data Link: frames, MAC addresses.\n- Network: packets, IP addresses (routing).\n- Transport: segments, TCP/UDP (end-to-end).\n- Session: establishes, manages, and terminates connections.\n- Presentation: data translation (encryption, compression).\n- Application: user-facing protocols (HTTP, FTP).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your foundational networking knowledge.\n\n**Breaking it down :**\n- Physical: bits, cables.\n- Data Link: frames, MAC addresses.\n- Network: packets, IP addresses (routing).\n- Transport: segments, TCP/UDP (end-to-end).\n- Session: establishes, manages, and terminates connections.\n- Presentation: data translation (encryption, compression).\n- Application: user-facing protocols (HTTP, FTP).\n\n**How to structure your spoken answer :**\nList layers in order. Briefly describe each layer's function. Mention the TCP/IP model as a simpler alternative.\n\n**Follow-up angle to anticipate :**\nBe ready to compare OSI and TCP/IP."],
  ["Software Engineering", "What is the TCP/IP model and its layers?", "tcp-ip-model", "Explain TCP/IP.", "**Direct answer :**\nTCP/IP model has 4 layers: Link (network access), Internet (IP), Transport (TCP/UDP), and Application. It's the practical model used in the Internet.\n\nKey points to remember:\n- Link: Ethernet, Wi-Fi.\n- Internet: IP, routing.\n- Transport: TCP (reliable), UDP (unreliable).\n- Application: HTTP, FTP, DNS.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of real-world networking.\n\n**Breaking it down :**\n- Link: Ethernet, Wi-Fi.\n- Internet: IP, routing.\n- Transport: TCP (reliable), UDP (unreliable).\n- Application: HTTP, FTP, DNS.\n\n**How to structure your spoken answer :**\nDefine TCP/IP. List layers. Compare with OSI.\n\n**Follow-up angle to anticipate :**\nBe ready to explain the differences between TCP and UDP."],
  ["Software Engineering", "What is the difference between TCP and UDP?", "tcp-vs-udp", "Compare TCP and UDP.", "**Direct answer :**\nTCP is connection-oriented, reliable, ordered, and has flow control. UDP is connectionless, unreliable, unordered, and has lower overhead. TCP for file transfer, UDP for streaming/real-time.\n\nKey points to remember:\n- TCP: three-way handshake, retransmission, congestion control.\n- UDP: no handshake, no retransmission, faster but lossy.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of transport protocols.\n\n**Breaking it down :**\n- TCP: three-way handshake, retransmission, congestion control.\n- UDP: no handshake, no retransmission, faster but lossy.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by reliability, ordering, and use cases. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss TCP's three-way handshake."],
  ["Software Engineering", "What is HTTP and its methods?", "http-methods", "Explain HTTP.", "**Direct answer :**\nHTTP (Hypertext Transfer Protocol) is an application-layer protocol for distributed, collaborative, hypermedia systems. Common methods: GET, POST, PUT, DELETE, PATCH, HEAD, OPTIONS.\n\nKey points to remember:\n- GET: retrieve resource.\n- POST: create resource.\n- PUT: replace resource.\n- DELETE: remove resource.\n- PATCH: partial update.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of web protocols.\n\n**Breaking it down :**\n- GET: retrieve resource.\n- POST: create resource.\n- PUT: replace resource.\n- DELETE: remove resource.\n- PATCH: partial update.\n\n**How to structure your spoken answer :**\nDefine HTTP. List methods with their idempotence and safety. Mention status codes.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss RESTful principles."],
  ["Software Engineering", "What are HTTP status codes (1xx, 2xx, 3xx, 4xx, 5xx)?", "http-status-codes", "Explain status codes.", "**Direct answer :**\nHTTP status codes indicate the result of a request. Categories: Informational (1xx), Success (2xx), Redirection (3xx), Client Error (4xx), Server Error (5xx).\n\nKey points to remember:\n- 1xx: Continue, Switching Protocols.\n- 2xx: 200 OK, 201 Created, 204 No Content.\n- 3xx: 301 Moved Permanently, 302 Found, 304 Not Modified.\n- 4xx: 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 429 Too Many Requests.\n- 5xx: 500 Internal Server Error, 502 Bad Gateway, 503 Service Unavailable.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of HTTP responses.\n\n**Breaking it down :**\n- 1xx: Continue, Switching Protocols.\n- 2xx: 200 OK, 201 Created, 204 No Content.\n- 3xx: 301 Moved Permanently, 302 Found, 304 Not Modified.\n- 4xx: 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 429 Too Many Requests.\n- 5xx: 500 Internal Server Error, 502 Bad Gateway, 503 Service Unavailable.\n\n**How to structure your spoken answer :**\nList categories with key examples. Explain each.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss handling specific status codes."],
  ["Software Engineering", "What is the difference between HTTP and HTTPS?", "http-vs-https", "Compare HTTP and HTTPS.", "**Direct answer :**\nHTTPS is HTTP over TLS/SSL, providing encryption, integrity, and authentication. It prevents eavesdropping and man-in-the-middle attacks. Port 443 vs 80.\n\nKey points to remember:\n- HTTP: plaintext.\n- HTTPS: encrypted, uses certificates.\n- HTTPS is now standard for all sites.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of secure communication.\n\n**Breaking it down :**\n- HTTP: plaintext.\n- HTTPS: encrypted, uses certificates.\n- HTTPS is now standard for all sites.\n\n**How to structure your spoken answer :**\nDefine both. Explain security benefits. Mention TLS handshake briefly.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss SSL/TLS certificates."],
  ["Software Engineering", "What is DNS and how does it work?", "dns", "Explain DNS.", "**Direct answer :**\nDNS (Domain Name System) translates domain names to IP addresses. It is a hierarchical, distributed database. Query flow: browser -> cache -> recursive resolver -> root -> TLD -> authoritative nameserver.\n\nKey points to remember:\n- Recursive resolver: does the legwork.\n- Root: points to TLD servers.\n- TLD: .com, .org, etc.\n- Authoritative: holds the actual DNS record.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of internet infrastructure.\n\n**Breaking it down :**\n- Recursive resolver: does the legwork.\n- Root: points to TLD servers.\n- TLD: .com, .org, etc.\n- Authoritative: holds the actual DNS record.\n\n**How to structure your spoken answer :**\nDefine DNS. Explain the resolution process. Mention caching.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss DNS record types (A, CNAME, MX)."],
  ["Software Engineering", "What is a load balancer in networking?", "load-balancer-networking", "Explain load balancer.", "**Direct answer :**\nA load balancer distributes incoming network traffic across multiple servers to ensure no single server is overwhelmed. It operates at Layer 4 (transport) or Layer 7 (application) of OSI.\n\nKey points to remember:\n- Layer 4: uses IP and port, faster.\n- Layer 7: uses HTTP headers, can route based on content.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of high availability.\n\n**Breaking it down :**\n- Layer 4: uses IP and port, faster.\n- Layer 7: uses HTTP headers, can route based on content.\n\n**How to structure your spoken answer :**\nDefine load balancer. Explain its role. Mention algorithms and types.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss health checks and session persistence."],
  ["Software Engineering", "What is a firewall and its types?", "firewall", "Explain firewall.", "**Direct answer :**\nA firewall is a network security system that monitors and controls incoming/outgoing network traffic based on predetermined rules. Types: packet-filtering, stateful, application-level (proxy), and next-generation (NGFW).\n\nKey points to remember:\n- Packet-filtering: checks headers.\n- Stateful: tracks connections.\n- Application: inspects payload.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of security.\n\n**Breaking it down :**\n- Packet-filtering: checks headers.\n- Stateful: tracks connections.\n- Application: inspects payload.\n\n**How to structure your spoken answer :**\nDefine firewall. Explain its purpose. List types and their differences.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss IDS/IPS."],
  ["Software Engineering", "What is a REST API and its constraints?", "rest-api-constraints", "Explain REST constraints.", "**Direct answer :**\nREST (Representational State Transfer) is an architectural style for networked applications. Its constraints: client-server, statelessness, cacheability, uniform interface, layered system, and code on demand (optional).\n\nKey points to remember:\n- Uniform interface: resources identified by URIs, manipulation via representations.\n- Stateless: no client context stored on server.\n- Cacheability: responses must indicate cacheability.\n- Layered: client cannot tell if it's connected directly to server or intermediary.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your API design knowledge.\n\n**Breaking it down :**\n- Uniform interface: resources identified by URIs, manipulation via representations.\n- Stateless: no client context stored on server.\n- Cacheability: responses must indicate cacheability.\n- Layered: client cannot tell if it's connected directly to server or intermediary.\n\n**How to structure your spoken answer :**\nDefine REST. List constraints with brief explanations. Mention that they lead to scalable, decoupled services.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss Richardson Maturity Model."],

  // ==================== OPERATING SYSTEMS (10) ====================
  ["Software Engineering", "What is a process and its states?", "process-states", "Explain process states.", "**Direct answer :**\nA process is a program in execution. Its states: New, Ready, Running, Blocked (Waiting), and Terminated. The OS schedules processes among these states.\n\nKey points to remember:\n- New: being created.\n- Ready: waiting for CPU.\n- Running: currently executing.\n- Blocked: waiting for I/O or event.\n- Terminated: finished.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your OS fundamentals.\n\n**Breaking it down :**\n- New: being created.\n- Ready: waiting for CPU.\n- Running: currently executing.\n- Blocked: waiting for I/O or event.\n- Terminated: finished.\n\n**How to structure your spoken answer :**\nDefine process. List states with transitions. Mention scheduling.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss context switching."],
  ["Software Engineering", "What is a thread and how does it differ from a process?", "thread-vs-process-os", "Compare thread and process.", "**Direct answer :**\nA thread is a lightweight unit of execution within a process; threads share the process's memory. Processes have separate memory spaces. Threads are cheaper to create and context-switch.\n\nKey points to remember:\n- Threads: share heap, code, files; communication easy.\n- Processes: isolated, require IPC.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of concurrency.\n\n**Breaking it down :**\n- Threads: share heap, code, files; communication easy.\n- Processes: isolated, require IPC.\n\n**How to structure your spoken answer :**\nDefine both. Contrast memory sharing, creation overhead, and communication.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss multithreading models."],
  ["Software Engineering", "What is deadlock and its necessary conditions?", "deadlock-conditions", "Explain deadlock.", "**Direct answer :**\nDeadlock occurs when two or more processes are blocked, each waiting for a resource held by another. Conditions: Mutual Exclusion, Hold and Wait, No Preemption, Circular Wait.\n\nKey points to remember:\n- Mutual exclusion: at least one resource is held exclusively.\n- Hold and wait: process holds resources while waiting for others.\n- No preemption: resources cannot be forcibly taken.\n- Circular wait: circular chain of processes waiting for resources.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of concurrency problems.\n\n**Breaking it down :**\n- Mutual exclusion: at least one resource is held exclusively.\n- Hold and wait: process holds resources while waiting for others.\n- No preemption: resources cannot be forcibly taken.\n- Circular wait: circular chain of processes waiting for resources.\n\n**How to structure your spoken answer :**\nDefine deadlock. List conditions. Explain how to prevent or avoid (e.g., resource allocation graph).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss deadlock avoidance (Banker's algorithm)."],
  ["Software Engineering", "What is the difference between paging and segmentation?", "paging-vs-segmentation", "Compare paging and segmentation.", "**Direct answer :**\nPaging divides memory into fixed-size blocks (pages) and logical memory into same-size pages; segmentation divides memory into variable-size logical units (segments). Paging is transparent to the programmer, segmentation is not.\n\nKey points to remember:\n- Paging: no external fragmentation, page table overhead.\n- Segmentation: supports sharing and protection, external fragmentation possible.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your memory management knowledge.\n\n**Breaking it down :**\n- Paging: no external fragmentation, page table overhead.\n- Segmentation: supports sharing and protection, external fragmentation possible.\n\n**How to structure your spoken answer :**\nDefine both. Contrast by size, fragmentation, and use.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss virtual memory and TLB."],
  ["Software Engineering", "What is virtual memory and why is it used?", "virtual-memory", "Explain virtual memory.", "**Direct answer :**\nVirtual memory allows a process to use more memory than physically available by using disk as backup. It provides isolation, simplifies programming, and enables paging/segmentation.\n\nKey points to remember:\n- Uses demand paging.\n- Page faults: when a page is not in RAM, load from disk.\n- Enables each process to have its own address space.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of memory abstraction.\n\n**Breaking it down :**\n- Uses demand paging.\n- Page faults: when a page is not in RAM, load from disk.\n- Enables each process to have its own address space.\n\n**How to structure your spoken answer :**\nDefine virtual memory. Explain its benefits and mechanisms (paging, swapping). Mention page replacement algorithms.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss page replacement algorithms (LRU, FIFO)."],
  ["Software Engineering", "What is a file system and its common types?", "file-systems", "Explain file systems.", "**Direct answer :**\nA file system controls how data is stored and retrieved on storage devices. Common types: FAT32, NTFS, ext4, APFS, ZFS. They provide hierarchical directory structures, permissions, and metadata.\n\nKey points to remember:\n- FAT: simple, widely compatible.\n- NTFS: Windows, supports permissions, journaling.\n- ext4: Linux, journaling.\n- ZFS: advanced, checksums, snapshots.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your knowledge of storage.\n\n**Breaking it down :**\n- FAT: simple, widely compatible.\n- NTFS: Windows, supports permissions, journaling.\n- ext4: Linux, journaling.\n- ZFS: advanced, checksums, snapshots.\n\n**How to structure your spoken answer :**\nDefine file system. List types and their characteristics. Mention inode structure.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss journaling vs non-journaling."],
  ["Software Engineering", "What is a system call and give examples?", "system-call", "Explain system call.", "**Direct answer :**\nA system call is a request from a user process to the OS kernel to perform privileged operations (I/O, process control). Examples: read(), write(), open(), fork(), exec().\n\nKey points to remember:\n- Provides a secure interface.\n- Mode switch from user to kernel mode.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of OS interfaces.\n\n**Breaking it down :**\n- Provides a secure interface.\n- Mode switch from user to kernel mode.\n\n**How to structure your spoken answer :**\nDefine system call. Explain its purpose. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how system calls are invoked (interrupts)."],
  ["Software Engineering", "What is the difference between multithreading and multiprocessing?", "multithreading-vs-multiprocessing", "Compare multithreading and multiprocessing.", "**Direct answer :**\nMultithreading: multiple threads within a single process sharing memory. Multiprocessing: multiple processes running on multiple CPUs. Threads are lighter, but a crash in one thread can affect others; processes are isolated.\n\nKey points to remember:\n- Multithreading: concurrency within a process.\n- Multiprocessing: parallel execution on multiple cores.\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of parallelism.\n\n**Breaking it down :**\n- Multithreading: concurrency within a process.\n- Multiprocessing: parallel execution on multiple cores.\n\n**How to structure your spoken answer :**\nDefine both. Contrast memory, isolation, and overhead.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss parallel programming models."],
  ["Software Engineering", "What is scheduling in OS and what are its algorithms?", "scheduling-algorithms", "Explain scheduling.", "**Direct answer :**\nScheduling is the method by which the OS allocates CPU time to processes. Common algorithms: FCFS, SJF, Round Robin, Priority, Multilevel Queue.\n\nKey points to remember:\n- FCFS: first come first served, simple but may cause convoy effect.\n- SJF: shortest job first, minimizes average waiting time.\n- Round Robin: preemptive, fair, time quantum.\n- Priority: high priority runs first, may cause starvation.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of resource allocation.\n\n**Breaking it down :**\n- FCFS: first come first served, simple but may cause convoy effect.\n- SJF: shortest job first, minimizes average waiting time.\n- Round Robin: preemptive, fair, time quantum.\n- Priority: high priority runs first, may cause starvation.\n\n**How to structure your spoken answer :**\nDefine scheduling. List algorithms with their pros and cons.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss priority inversion and aging."],
  ["Software Engineering", "What is the difference between a kernel and a shell?", "kernel-vs-shell", "Compare kernel and shell.", "**Direct answer :**\nThe kernel is the core of the OS, managing hardware and system resources. The shell is a user interface (CLI) that interprets commands and interacts with the kernel.\n\nKey points to remember:\n- Kernel: runs in privileged mode, handles interrupts, memory, processes.\n- Shell: runs in user mode, provides user interaction (bash, zsh).\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your OS understanding.\n\n**Breaking it down :**\n- Kernel: runs in privileged mode, handles interrupts, memory, processes.\n- Shell: runs in user mode, provides user interaction (bash, zsh).\n\n**How to structure your spoken answer :**\nDefine both. Contrast their roles and levels.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss types of kernels (monolithic, micro)."],

  // ==================== CODING PRINCIPLES & BEST PRACTICES (10) ====================
  ["Software Engineering", "What is the DRY principle?", "dry", "Explain DRY.", "**Direct answer :**\nDRY (Don't Repeat Yourself) emphasizes avoiding duplication of code and logic. Duplication leads to maintenance overhead and inconsistencies. Use abstractions, functions, and modules to reuse code.\n\nKey points to remember:\n- Duplication: copy-paste, similar logic.\n- Solutions: extract methods, use inheritance, apply design patterns.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of clean code.\n\n**Breaking it down :**\n- Duplication: copy-paste, similar logic.\n- Solutions: extract methods, use inheritance, apply design patterns.\n\n**How to structure your spoken answer :**\nDefine DRY. Explain its importance. Give an example of violation and fix.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the balance with 'Rule of Three'."],
  ["Software Engineering", "What is the KISS principle?", "kiss", "Explain KISS.", "**Direct answer :**\nKISS (Keep It Simple, Stupid) advocates for simplicity in design. Avoid over-engineering; solutions should be as simple as possible while meeting requirements.\n\nKey points to remember:\n- Simple code is easier to understand, maintain, and test.\n- Avoid unnecessary complexity, premature optimization.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your design philosophy.\n\n**Breaking it down :**\n- Simple code is easier to understand, maintain, and test.\n- Avoid unnecessary complexity, premature optimization.\n\n**How to structure your spoken answer :**\nDefine KISS. Explain its benefits. Give an example of over-engineering.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss YAGNI."],
  ["Software Engineering", "What is YAGNI?", "yagni", "Explain YAGNI.", "**Direct answer :**\nYAGNI (You Aren't Gonna Need It) is a principle from Extreme Programming that advises against adding functionality until it is actually needed. It prevents wasted effort on speculative features.\n\nKey points to remember:\n- Focus on current requirements.\n- Refactor when needed; don't add features 'just in case'.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of agile development.\n\n**Breaking it down :**\n- Focus on current requirements.\n- Refactor when needed; don't add features 'just in case'.\n\n**How to structure your spoken answer :**\nDefine YAGNI. Explain its purpose. Give an example.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how it relates to iterative development."],
  ["Software Engineering", "What is the difference between a framework and a library?", "framework-vs-library", "Compare framework and library.", "**Direct answer :**\nA library is a collection of functions you call; it provides specific functionality. A framework is a structure that calls your code; it dictates the flow of control (inversion of control). Libraries are more flexible; frameworks provide more structure.\n\nKey points to remember:\n- Library: you choose when to use it.\n- Framework: you plug into it, it controls the flow (e.g., Spring).\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of software architecture.\n\n**Breaking it down :**\n- Library: you choose when to use it.\n- Framework: you plug into it, it controls the flow (e.g., Spring).\n\n**How to structure your spoken answer :**\nDefine both. Contrast by control flow. Give examples.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to use each."],
  ["Software Engineering", "What is refactoring and why is it important?", "refactoring", "Explain refactoring.", "**Direct answer :**\nRefactoring is restructuring existing code without changing its external behavior. It improves readability, reduces complexity, and enhances maintainability. It's an ongoing process in agile development.\n\nKey points to remember:\n- Small, incremental changes.\n- Ensures code stays clean as requirements evolve.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your commitment to code quality.\n\n**Breaking it down :**\n- Small, incremental changes.\n- Ensures code stays clean as requirements evolve.\n\n**How to structure your spoken answer :**\nDefine refactoring. Explain its benefits. Give examples (extract method, rename variable).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss when to refactor."],
  ["Software Engineering", "What is version control and why is it used?", "version-control", "Explain version control.", "**Direct answer :**\nVersion control tracks changes to files over time, allowing multiple developers to collaborate, revert to previous versions, and manage releases. Examples: Git, SVN.\n\nKey points to remember:\n- Distributed (Git) vs centralized (SVN).\n- Branching, merging, pull requests.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your collaboration skills.\n\n**Breaking it down :**\n- Distributed (Git) vs centralized (SVN).\n- Branching, merging, pull requests.\n\n**How to structure your spoken answer :**\nDefine version control. List its benefits. Mention Git as the de facto standard.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss Git workflows."],
  ["Software Engineering", "What is CI/CD?", "ci-cd", "Explain CI/CD.", "**Direct answer :**\nCI (Continuous Integration) is the practice of automatically building and testing code on every push. CD (Continuous Delivery/Deployment) automates the release process, enabling frequent, reliable deployments.\n\nKey points to remember:\n- CI: merge code frequently, run tests, catch issues early.\n- CD: automatically deploy to staging/production.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your DevOps knowledge.\n\n**Breaking it down :**\n- CI: merge code frequently, run tests, catch issues early.\n- CD: automatically deploy to staging/production.\n\n**How to structure your spoken answer :**\nDefine CI and CD. Explain their benefits. Mention tools: Jenkins, GitHub Actions.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss the difference between delivery and deployment."],
  ["Software Engineering", "What is the difference between agile and waterfall?", "agile-vs-waterfall", "Compare Agile and Waterfall.", "**Direct answer :**\nWaterfall is a linear, sequential model; each phase completes before the next. Agile is iterative, incremental, and adaptive; it embraces change and delivers value frequently.\n\nKey points to remember:\n- Waterfall: rigid, long feedback cycles.\n- Agile: flexible, short cycles (sprints).\n\nThe important point is that neither option is universally better. The correct choice depends on the required behavior, performance characteristics, complexity, and operational constraints.\n\n**Why this is asked :**\nInterviewers ask this to test your project management understanding.\n\n**Breaking it down :**\n- Waterfall: rigid, long feedback cycles.\n- Agile: flexible, short cycles (sprints).\n\n**How to structure your spoken answer :**\nDefine both. Contrast approach, flexibility, and customer involvement.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss Scrum and Kanban."],
  ["Software Engineering", "What is a code review and why is it important?", "code-review", "Explain code review.", "**Direct answer :**\nA code review is a process where developers examine each other's code to find bugs, improve quality, and share knowledge. It promotes consistency, catches issues early, and fosters collaboration.\n\nKey points to remember:\n- Automated vs manual.\n- Benefits: learning, defect prevention, design improvement.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your collaborative skills.\n\n**Breaking it down :**\n- Automated vs manual.\n- Benefits: learning, defect prevention, design improvement.\n\n**How to structure your spoken answer :**\nDefine code review. Explain its importance. Mention best practices (small changes, constructive feedback).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to give effective code reviews."],
  ["Software Engineering", "What is technical debt?", "technical-debt", "Explain technical debt.", "**Direct answer :**\nTechnical debt is the implied cost of additional rework caused by choosing an easy (quick) solution now instead of a better approach that would take longer. It can be intentional (to meet deadlines) or unintentional (poor design).\n\nKey points to remember:\n- Can be refactored later.\n- Too much debt slows development.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your understanding of trade-offs.\n\n**Breaking it down :**\n- Can be refactored later.\n- Too much debt slows development.\n\n**How to structure your spoken answer :**\nDefine technical debt. Explain its causes and effects. Mention strategies to manage it.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how to pay off technical debt."],

  // ==================== BEHAVIORAL & PROCESS (15) ====================
  ["Software Engineering", "Tell me about yourself.", "tell-me-about-yourself", "Answer: Tell me about yourself.", "**Direct answer :**\nI am a software engineer with X years of experience in building scalable applications. My expertise includes [technologies]. I'm passionate about solving complex problems and continuously learning. In my current role, I led the development of [project], improving [metric].\n\nKey points to remember:\n- Start with current role and past experience.\n- Highlight key achievements.\n- End with why you're interested in this role.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to break the ice and get a summary of your background.\n\n**Breaking it down :**\n- Start with current role and past experience.\n- Highlight key achievements.\n- End with why you're interested in this role.\n\n**How to structure your spoken answer :**\nUse the Present-Past-Future formula: current role, previous experience, future aspirations.\n\n**Follow-up angle to anticipate :**\nBe ready to dive deeper into any project you mention."],
  ["Software Engineering", "What is your greatest strength?", "strength", "Answer: Greatest strength.", "**Direct answer :**\nMy greatest strength is my problem-solving ability. I approach issues methodically and enjoy tackling challenging bugs. For example, I resolved a critical performance issue by refactoring a caching layer, reducing latency by 40%.\n\nKey points to remember:\n- Choose a strength relevant to the job.\n- Provide evidence with a specific example.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to assess your self-awareness and fit.\n\n**Breaking it down :**\n- Choose a strength relevant to the job.\n- Provide evidence with a specific example.\n\n**How to structure your spoken answer :**\nState the strength, give a brief example, and tie it to the job requirements.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss a weakness (if asked)."],
  ["Software Engineering", "What is your greatest weakness?", "weakness", "Answer: Greatest weakness.", "**Direct answer :**\nI sometimes struggle with delegating tasks because I want to ensure they are done correctly. However, I've been working on trusting my team and providing clear guidelines, which has improved our productivity.\n\nKey points to remember:\n- Choose a genuine but not critical weakness.\n- Show steps you're taking to improve.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test honesty and self-improvement.\n\n**Breaking it down :**\n- Choose a genuine but not critical weakness.\n- Show steps you're taking to improve.\n\n**How to structure your spoken answer :**\nState weakness, explain impact, describe improvement efforts.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how you handle feedback."],
  ["Software Engineering", "Why do you want to work here?", "why-this-company", "Answer: Why this company.", "**Direct answer :**\nI admire [Company]'s innovative culture and commitment to [product/mission]. I'm excited about the opportunity to work on [specific technology/problem] and contribute to impactful projects. I also value the company's emphasis on [value, e.g., learning, teamwork].\n\nKey points to remember:\n- Research company mission, products, culture.\n- Connect your skills and goals to their needs.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to see if you've done research and are genuinely interested.\n\n**Breaking it down :**\n- Research company mission, products, culture.\n- Connect your skills and goals to their needs.\n\n**How to structure your spoken answer :**\nMention specific aspects you like, tie to your experience, and express enthusiasm.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss what you know about their current challenges."],
  ["Software Engineering", "Tell me about a time you faced a challenging bug.", "challenging-bug", "Answer: Challenging bug.", "**Direct answer :**\nWe had a production issue where users were intermittently getting 504 errors. After analyzing logs and tracing, I discovered a misconfigured timeout in a service. I increased the timeout and added retries, which resolved the issue. I also documented the root cause.\n\nKey points to remember:\n- Use STAR method (Situation, Task, Action, Result).\n- Show analytical approach and learning.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your problem-solving and debugging skills.\n\n**Breaking it down :**\n- Use STAR method (Situation, Task, Action, Result).\n- Show analytical approach and learning.\n\n**How to structure your spoken answer :**\nDescribe the situation, the steps you took, the outcome, and what you learned.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how you prevented similar issues."],
  ["Software Engineering", "Describe a time you had to work under pressure.", "work-under-pressure", "Answer: Under pressure.", "**Direct answer :**\nDuring a major product launch, we discovered a critical bug the night before. I coordinated with the team, prioritized fixes, and ran extra tests. We deployed a hotfix on time, and the launch was successful. I stayed calm and focused on the solution.\n\nKey points to remember:\n- Show how you managed stress and kept the team focused.\n- Highlight the positive outcome.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to assess your resilience and time management.\n\n**Breaking it down :**\n- Show how you managed stress and kept the team focused.\n- Highlight the positive outcome.\n\n**How to structure your spoken answer :**\nDescribe the situation, your actions, and the resolution.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how you handle tight deadlines."],
  ["Software Engineering", "Tell me about a time you disagreed with a team member.", "disagreement", "Answer: Disagreement.", "**Direct answer :**\nI disagreed with a colleague on the choice of a database. We had a constructive discussion, I presented data on scalability, and we agreed on a middle ground. The project succeeded, and we both learned from the experience.\n\nKey points to remember:\n- Show respect for others' opinions.\n- Emphasize collaboration and data-driven decisions.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to evaluate your interpersonal and conflict resolution skills.\n\n**Breaking it down :**\n- Show respect for others' opinions.\n- Emphasize collaboration and data-driven decisions.\n\n**How to structure your spoken answer :**\nDescribe the disagreement, how you approached it, and the eventual resolution.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how you handle feedback."],
  ["Software Engineering", "How do you stay updated with technology?", "staying-updated", "Answer: Staying updated.", "**Direct answer :**\nI read tech blogs, listen to podcasts, and follow experts on social media. I also take online courses and contribute to open-source projects. Recently, I completed a course on Kubernetes to deepen my knowledge.\n\nKey points to remember:\n- Mention specific resources.\n- Show proactive learning.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to gauge your passion for learning.\n\n**Breaking it down :**\n- Mention specific resources.\n- Show proactive learning.\n\n**How to structure your spoken answer :**\nList activities (reading, courses, side projects) and give an example.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss a recent technology you learned."],
  ["Software Engineering", "What is your approach to testing?", "testing-approach", "Answer: Testing approach.", "**Direct answer :**\nI believe in a comprehensive testing pyramid: unit tests for individual components, integration tests for interactions, and end-to-end tests for critical flows. I write tests before or alongside code (TDD) to ensure quality and prevent regressions.\n\nKey points to remember:\n- Mention unit, integration, E2E.\n- Discuss automation and CI integration.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your commitment to quality.\n\n**Breaking it down :**\n- Mention unit, integration, E2E.\n- Discuss automation and CI integration.\n\n**How to structure your spoken answer :**\nExplain your testing philosophy and give examples of tools you use (JUnit, Selenium, etc.).\n\n**Follow-up angle to anticipate :**\nBe ready to discuss your experience with a specific testing framework."],
  ["Software Engineering", "How do you handle a project with changing requirements?", "changing-requirements", "Answer: Changing requirements.", "**Direct answer :**\nI embrace change as it's part of agile development. I communicate with stakeholders to prioritize features and adjust plans accordingly. I ensure the code is modular and maintainable to accommodate changes. Regular demos and feedback loops help manage expectations.\n\nKey points to remember:\n- Emphasize communication and flexibility.\n- Show how you keep code adaptable.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your adaptability.\n\n**Breaking it down :**\n- Emphasize communication and flexibility.\n- Show how you keep code adaptable.\n\n**How to structure your spoken answer :**\nExplain your process: prioritize, adjust, communicate.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss a specific instance of change."],
  ["Software Engineering", "What is your favorite programming language and why?", "favorite-language", "Answer: Favorite language.", "**Direct answer :**\nMy favorite is Java because of its mature ecosystem, strong typing, and vast frameworks. However, I'm also comfortable with Python for scripting and prototyping. I choose language based on project needs.\n\nKey points to remember:\n- Mention reasons (ecosystem, performance, community).\n- Show you're not dogmatic.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to understand your preferences and expertise.\n\n**Breaking it down :**\n- Mention reasons (ecosystem, performance, community).\n- Show you're not dogmatic.\n\n**How to structure your spoken answer :**\nState language, give reasons, and show versatility.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss a project where you used that language."],
  ["Software Engineering", "Describe a time you mentored someone.", "mentorship", "Answer: Mentorship.", "**Direct answer :**\nI mentored a junior developer who was struggling with our codebase. I conducted weekly code review sessions, explained design patterns, and pair-programmed on complex features. After three months, he was independently delivering features. It was rewarding to see his growth.\n\nKey points to remember:\n- Show how you invested time.\n- Highlight the positive outcome.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your leadership and collaboration skills.\n\n**Breaking it down :**\n- Show how you invested time.\n- Highlight the positive outcome.\n\n**How to structure your spoken answer :**\nDescribe the situation, your mentoring approach, and the result.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss your mentoring style."],
  ["Software Engineering", "What is your process for debugging?", "debugging-process", "Answer: Debugging.", "**Direct answer :**\nI start by reproducing the issue, checking logs, and isolating the problem. I use breakpoints and logging to trace execution. Once I find the root cause, I write a test to reproduce it, fix it, and ensure no regressions.\n\nKey points to remember:\n- Steps: reproduce, isolate, fix, test.\n- Mention tools (debugger, profiler).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to assess your technical approach.\n\n**Breaking it down :**\n- Steps: reproduce, isolate, fix, test.\n- Mention tools (debugger, profiler).\n\n**How to structure your spoken answer :**\nOutline your systematic approach.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss a difficult bug you debugged."],
  ["Software Engineering", "How do you prioritize tasks?", "prioritization", "Answer: Prioritization.", "**Direct answer :**\nI prioritize based on business impact and urgency. I use frameworks like Eisenhower Matrix (urgent/important) and collaborate with product managers. I also consider dependencies and risks. I break down large tasks into smaller ones to track progress.\n\nKey points to remember:\n- Explain your criteria.\n- Mention tools (Jira, Trello).\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to test your time management.\n\n**Breaking it down :**\n- Explain your criteria.\n- Mention tools (Jira, Trello).\n\n**How to structure your spoken answer :**\nDescribe your approach with an example.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss a time you had to reprioritize."],
  ["Software Engineering", "What are your career goals?", "career-goals", "Answer: Career goals.", "**Direct answer :**\nI aim to grow into a senior/lead role where I can architect solutions and mentor others. I want to work on impactful projects and continue learning. In the long term, I see myself contributing to open-source and sharing knowledge through blogging.\n\nKey points to remember:\n- Be specific but realistic.\n- Show ambition and alignment with the role.\n\nA strong interview answer should connect the definition to how the concept works internally, its important trade-offs, and one realistic use case. The goal is not only to name the concept but to explain why and when it is useful.\n\n**Why this is asked :**\nInterviewers ask this to see if your goals align with the company's growth.\n\n**Breaking it down :**\n- Be specific but realistic.\n- Show ambition and alignment with the role.\n\n**How to structure your spoken answer :**\nState short-term and long-term goals, and how this role fits.\n\n**Follow-up angle to anticipate :**\nBe ready to discuss how you plan to achieve them."],
];

const prisma = new PrismaClient();

const buildWhyInterviewersAsk = (question: string, shortDescription: string) =>
  `Interviewers ask this to check whether you can explain software engineering concepts clearly and connect them to practical engineering decisions. ${shortDescription} A strong response should address the purpose, the relevant trade‑offs, and how you would verify the result rather than reciting a definition.`;

const buildCommonMistakes = (question: string) => [
  `Giving a memorized definition without explaining how it applies to: ${question}`,
  "Listing features without explaining the safety, performance, or operational trade‑off.",
  "Ignoring security boundaries, persistence, failure handling, or how the solution would be tested.",
];

async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "software-engineering" },
    update: { name: "Software Engineering", group: "Technology", description: "Software Engineering interview questions." },
    create: { name: "Software Engineering", slug: "software-engineering", group: "Technology", description: "Software Engineering interview questions." },
  });
  const subcategory = await prisma.subcategory.upsert({
    where: { categoryId_slug: { categoryId: category.id, slug: "software-engineering" } },
    update: {},
    create: { name: "Software Engineering", slug: "software-engineering", categoryId: category.id },
  });

  for (let topicIndex = 0; topicIndex < topics.length; topicIndex += 1) {
    const [, question, slug, shortDescription, sampleAnswer] = topics[topicIndex];
    const commonMistakes = buildCommonMistakes(question);
    const followUpQuestions = [
      topics[(topicIndex + 1) % topics.length][1],
      topics[(topicIndex + 2) % topics.length][1],
      topics[(topicIndex + 3) % topics.length][1],
    ];
    await prisma.interviewQuestion.upsert({
      where: { slug },
      update: {
        question,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation: buildWhyInterviewersAsk(question, shortDescription),
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: [],
        commonMistakes,
        followUpQuestions,
        tags: ["Software Engineering"],
        isPublished: true,
      },
      create: {
        question,
        slug,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription,
        explanation: buildWhyInterviewersAsk(question, shortDescription),
        sampleAnswer,
        detailedAnswer: sampleAnswer,
        keyPoints: [],
        commonMistakes,
        followUpQuestions,
        tags: ["Software Engineering"],
        isPublished: true,
      },
    });
  }

  console.log(`Imported ${topics.length} Software Engineering questions.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());

export const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");